WITH payload AS (SELECT $archive_payload$[{"id":"08fbef8f-54b2-5cf3-979a-1c7d61f0060b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة زوجة بنفقتها املاضية -مطالبة أم بزيادة نفقة ابنها -حكم بعدم استحقاق الزوجة لنفقتها املاضية لثبوت نشوزها -تقدير نفقة االبن عن طريق قسم اخلبراء -حكم بزيادة نفقة االبن -خروج الزوجة من بيت الزوج بغير إذنه يعد نشوز ا .","document_number":"34270475","case_number":"33677976","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"نفقة -مطالبة زوجة بنفقتها املاضية -مطالبة أم بزيادة نفقة ابنها -حكم بعدم استحقاق الزوجة لنفقتها املاضية لثبوت نشوزها -تقدير نفقة االبن عن طريق قسم اخلبراء -حكم بزيادة نفقة االبن -خروج الزوجة من بيت الزوج بغير إذنه يعد نشوز ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34270475 :‬‬\n                   ‫َر ْق ُم الدعوى‪33677976 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34318608‬تاريخه‪1434/9/14 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة زوجــة بنفقتهــا املاضيــة ‪ -‬مطالبــة أم بزيــادة نفقــة‬\n‫ابنهــا ‪ -‬حكــم بعــدم اســتحقاق الزوجــة لنفقتهــا املاضيــة لثبــوت‬\n‫نشــوزها ‪ -‬تقديــر نفقــة االبــن عــن طريــق قســم اخلبــراء ‪ -‬حكــم بزيــادة‬\n‫نفقــة االبــن ‪ -‬خــروج الزوجــة مــن بيــت الــزوج بغيــر إذنــه يعــد نشــوز ًا ‪.‬‬\n\n\n\n\n                                ‫‪ .1‬قوله تعالى { ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِتهِ}‬\n‫‪ .2‬جــاء يف املغنــي ‪ 4/11‬عنــد ذكــره ملــا يعــد نشــوز ًا مســقط ًا للنفقــة‬\n                              ‫(وكــذا إن انتقلــت مــن منزلــه بغيــر إذنــه)‬\n‫‪.3‬وجــاء يف كشــاف القنــاع ‪ 138/13‬مــا نصــه ( أو انتقلــت مــن منزلــه‬\n‫بغيــر إذنــه فــا نفقــة لهــا لنشــوزها ولــو كان خروجهــا مــن منزلــه يف‬\n                                                      ‫غيبتــه بغيــر إذنــه فــا نفقــة )‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا ودخــل بهــا وأجنبــت‬\n‫منــه ابنـ ًا يبلــغ مــن العمــر ســنة وأربعــة أشــهر ثــم طلقهــا طلقــة رجعيــة يف‬\n‫‪1433/11/15‬ه ـ مبوجــب صــك الطــاق وال زالــت يف العــدة الشــرعية‬\n‫وقــد حصــل خــاف بــن املدعيــة واملدعــى عليــه فخرجــت بطوعهــا إلــى‬\n‫بيــت والدهــا ألنهــا كرهــت البقــاء مــع الــزوج لســوء املعاملــة وكونــه‬\n                                                                                               ‫‪212‬‬\n\f      ‫ال يحســن العشــرة وطالبــت بإلــزام املدعــى عليــه بــأن يدفــع نفقــة املــدة‬\n      ‫املاضيــة خــال املــدة التــي مكثــت فيهــا يف بيــت والدهــا كمــا طالبــت‬\n      ‫بزيــادة النفقــة الشــهرية البنهــا حيــث إن والــده املدعــى عليــه ينفــق عليــه‬\n      ‫نفقــة شــهرية قدرهــا خمســمائة ريــال وهــي ال تكفــي ‪ -‬أجــاب املدعــى‬\n      ‫عليــه باملصادقــة علــى الدعــوى جملــة وتفصيــا وقــرر أن املدعيــة ال‬\n      ‫تســتحق النفقــة ألنهــا ناشــز وأنــه ال يســتطيع زيــادة النفقــة علــى ابنــه‬\n      ‫لقلــة دخلــه الشــهري ولوجــود التزامــات شــهرية عليــه ‪ -‬مت تقديــر نفقــة‬\n      ‫شــهرية لالبــن مــن قبــل قســم اخلبــراء باحملكمــة ســتمائة ريــال ‪ -‬تصــادق‬\n      ‫الطرفــان بــأن املدعــى عليــه انقطــع عن تســليم نفقة االبن منذ أن تقدمت‬\n      ‫املدعيــة بدعواهــا املنظــورة ‪ -‬قــرر ناظــر القضيــة ولألســباب املرصــودة‬\n      ‫أن املدعيــة ذكــرت أنهــا خرجــت مــن منــزل زوجهــا بطوعهــا وبــدون‬\n      ‫إذن زوجهــا فتعتبــر ناشــز ًا فــا نفقــة لهــا وال ســكنى ولــذا فقــد صــدر‬\n      ‫احلكــم بــرد دعــوى املدعيــة مطالبتهــا بنفقتهــا مــن تاريــخ خروجهــا مــن‬\n      ‫منــزل زوجهــا حتــى اآلن لكونهــا خرجــت بطوعهــا واختيارهــا بــا ســبب‬\n      ‫شــرعي ‪ -‬كمــا صــدر احلكــم علــى املدعــى عليــه بــأن يدفــع للمدعيــة‬\n      ‫نفقــة شــهرية لالبــن قدرهــا ســتمائة ريــال شــاملة لألشــهر التــي لــم يســلم‬\n      ‫فيهــا املدعــى عليــه النفقــة للمدعيــة مــن تاريــخ رفــع هــذه الدعــوى ‪ -‬قــرر‬\n      ‫الطرفــان عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف بالريــاض‬\n                                                             ‫باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫‪213‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .......‬القاضــي يف احملكمــة العامــة مبحافظــة اخلــرج وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج‪/‬‬\n‫املكلــف برقــم ‪ 33677976‬وتاريــخ ‪ 1433/11/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332123722‬وتاريــخ ‪ 1433/11/27‬ه ـ ففــي‬\n‫يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪08‬وفيهــا حضــرت ‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ .......‬ومعهــا أخوهــا املعــرف بهــا ‪ .......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .......‬وادعــت علــى احلاضــر معهــا قائلــة يف حتريــر دعواهــا‬\n‫عليــه لقــد عقــد لــي علــى املدعــى عليــه هــذا احلاضــر بعقــد نــكاح‬\n‫صحيــح ودخــل بــي الدخــول الشــرعي وقــد اجنبــت منــه ابن ـ ًا اســمه‬\n‫‪ .......‬ويبلــغ مــن العمــر ســنه وأربعــة أشــهر ثــم طلقنــي طلقــة رجعيــه يف‬\n‫‪1433/11/15‬ه ـ مبوجــب صــك إثبــات الطــاق الصــادر مــن احملكمــة‬\n‫العامــة باخلــرج برقــم ‪ 33455560‬يف ‪1433/11/15‬ه ـ وال زلــت يف العــدة‬\n‫الشــرعية وقــد حصــل بينــي وبينــه شــقاق ونــزاع قبــل الطــاق فخرجــت‬\n‫علــى إثــره بطوعــي واختيــاري مــن منــزل زوجــي إلــى منــزل والــدي منــذ‬\n‫تاريــخ ‪1433/5/18‬ه ـ حيــث حضــر أخــي وأخذنــي مــن منــزل املدعــى‬\n‫عليــه وذلــك أننــي كرهــت البقــاء معــه يف منزلــه ملــا لقيتــه مــن ســوء‬\n‫معاملتــه ولكونــه ال يحســن عشــرتي لــذا فإننــي اطلــب إلــزام املدعــى‬\n‫عليــه بــأن يدفــع لــي نفقــة املــدة املاضيــة خــال املــدة التــي مكثتهــا يف‬\n‫منــزل والــدي مــن خروجــي مــن منــزل املدعــى عليــه يف ‪1433/5/18‬ه ـ‬\n\n                                                                                     ‫‪214‬‬\n\f      ‫حتــى اآلن كمــا اطلــب إلــزام املدعــى عليــه بزيــادة النفقــة الشــهرية‬\n      ‫البنــي حيــث إن والــده ينفــق عليــه نفقــه شــهرية قدرهــا خمســمائة‬\n      ‫ريــال يف الشــهر وهــي التكفــي للنفقــة هكــذا ادعــت وبســؤال املدعــى‬\n      ‫عليــه أجــاب بقولــه ماذكرتــه املدعيــة مــن عقــدي عليهــا بعقــد نــكاح‬\n      ‫صحيــح ودخولــي بهــا الدخــول الشــرعي وأنهــا أجنبــت لــي ابن ـ ًا اســمه‬\n      ‫‪ .......‬يبلــغ مــن العمــر ســنة وأربعــة أشــهر وأننــي طلقتهــا طلقــة رجعيــة يف‬\n      ‫‪1433/11/15‬ه ـ وأنهــا خرجــت مــن منــزل الزوجيــة إلــى منــزل والدهــا‬\n      ‫يف ‪1433/5/18‬ه ـ وأننــي لــم انفــق عليهــا خــال هــذه املــدة فهــذا كلــه‬\n      ‫صحيــح وأنــا اقــره وأمــا مطالبــة املدعيــة بالنفقــة املاضيــة فــا تســتحقها‬\n      ‫علـ َـي ألنهــا هــي التــي خرجــت مــن منزلــي وهــي ناشــز فــا تســتحق علـ َـى‬\n      ‫نفقــة فأنــا لــم اخرجهــا بــل هــي التــي خرجــت حيــث حضــر أخوهــا‬\n      ‫وأخذهــا دون إذنٍ منــي واطلــب رد دعواهــا ضــدي بخصــوص طلبهــا‬\n      ‫النفقــة وأمــا مطالبتهــا بخصــوص زيــادة النفقــة لالبــن فأنــا انفــق عليــه‬\n      ‫خمســمائة ريــال شــهري ًا وهــي كافيــة إذ أننــي أعمــل يف بلديــة ‪.........‬‬\n      ‫براتــب شــهري قــدره ثالثــة آالف وخمســمائة ريــال كمــا أننــي مــؤذن‬\n      ‫ألحــد مســاجد اخلــرج واســتلم مكافــأة قدرهــا ألــف وأربعمائــة ريــال‬\n      ‫ومجمــوع دخلــي الشــهري أربعــة آالف وتســعمائة ريــال وعلـ َـى اســتقطاع‬\n      ‫مــن راتبــي قــدره ألفــي ريــال شــهري ًا وال اســتطيع أن ادفــع أكثــر مــن‬\n      ‫خمســمائة ريــال نفقــة البنــي هكــذا أجــاب وبعــرض جــواب املدعــى عليه‬\n      ‫علــى املدعيــة صادقتــه علــى ماذكــره بخصــوص خروجهــا مــن منزلــه‬\n      ‫بعــد حصــول الشــقاق واخلــاف بينهمــا وأن املدعــى عليــه لــم يخرجهــا و‬\n      ‫إمنــا هــي التــي خرجــت مــن منزلــه بطوعهــا واختيارهــا وأمــا ماذكــره مــن‬\n      ‫أن النفقــه كافيــة وأن عليــه التزامــات ماليــة فأجابــت عــن ذلــك بقولهــا‬\n\n\n‫‪215‬‬\n\f‫إننــي ال اعلــم عمــا ذكــره املدعــى عليــه مــن وجــود التزامــات ماليــة عليــه‬\n‫واطلــب التحقــق مــن ذلــك هكــذا أجابــت ثــم رأيــت رفــع اجللســة للكتابة‬\n‫لقســم اخلبــراء باحملكمــة للنظــر يف النفقــة الشــهرية لالبــن ‪.........‬البالــغ‬\n‫قدرهــا خمســمائة ريــال هــل هــي مناســبة حلــال املنفــق واملنفــق عليــه بعــد‬\n‫التحقــق مــن االلتزامــات املاليــة التــي ذكــر املدعــى عليــه أنهــا تســتقطع‬\n‫مــن راتبــه وحلــن الكتابــة وورود االجابــة جــرى رفــع اجللســة ‪ .‬ويف جلســة‬\n‫أخــرى افتتحــت اجللســة يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا يف‬\n‫يــوم الســبت املوافــق ‪1434/07/08‬ه ـ وفيهــا حضــرت املدعيــة ومعهــا‬\n‫أخوهــا ‪.........‬املعــرف بهــا احلاضــر يف اجللســة املاضيــة كمــا حضــر‬\n‫املدعــى عليــه وقــد وردنــا خطــاب رئيــس قســم اخلبــراء باحملكمــة رقــم‬\n‫‪ 34/773511‬يف ‪1434/04/20‬ه ـ املرفــق بــه قــرار اخلبــراء املتضمــن مــا‬\n‫نــص احلاجــة منــه (وبعــد االطــاع علــى كامــل الدعــوى ومقــدار راتــب‬\n‫املدعــى عليــه املوضــح باخلطــاب املرفــق يــرى األعضــاء أن تكــون نفقــة‬\n‫االبــن املســتقبلية (‪ )600‬ريــال شــهري ًا وقــد مت هــذا التقديــر مراعــاة حلــال‬\n                                                                          ‫املنفــق)‪.‬‬\n‫ثــم قــررت الزوجــة قائلــة إننــي لــم اســتلم مــن املدعــى عليــه نفقــة البنــه‬\n‫منــذ أن تقدمــت بدعــواي إلــى احملكمــة بتاريــخ ‪1433/11/27‬ه ـ‬\n‫واطلــب إلــزام املدعــى عليــه بــأن يدفــع لــي نفقــة هــذه املــدة هكــذا قررت‬\n‫وبعــرض ذلــك علــى املدعــى عليــه صادقهــا علــى مــا ذكرتــه مــن أنــه لــم‬\n‫يســلمها نفقــة البنــه منــذ أن تقدمــت بدعواهــا إلــى احملكمــة حتــى اآلن‬\n‫وبعــد التأمــل فيمــا تقــدم مــن الدعــوى واإلجابــة ومــا جــاء يف قــرار قســم‬\n‫اخلبــراء باحملكمــة بخصــوص تقديــر نفقــة االبــن ‪.........‬مببلــغ ســتمائة‬\n‫ريــال بزيــادة مائــة ريــال عــن النفقــة التــي كان يســلمها املدعــى عليــه‬\n\n\n                                                                                       ‫‪216‬‬\n\f      ‫للمدعيــة وقــد مت هــذا التقديــر للنفقــة بعــد االطــاع علــى حــال املنفــق‬\n      ‫ولقــول اهلل تعالــى ( لينفــق ذو ســعة مــن ســعته ) ومبــا أن املدعيــة قــد‬\n      ‫ذكــرت أن خروجهــا مــن منــزل زوجهــا إلــى منــزل والدهــا كان بغيــر‬\n      ‫إذن مــن زوجهــا وإمنــا كان بطوعهــا واختيارهــا ملــا كرهــت البقــاء معــه‬\n      ‫وهــذا ال يبــرر لهــا اخلــروج مــن منزلــه وملــا قــرره عامــة الفقهــاء مــن أن‬\n      ‫املــرأة إذا خرجــت مــن بيــت زوجهــا بغيــر إذنــه بــا ســبب شــرعي يقتضــي‬\n      ‫خروجهــا أنهــا تعتبــر ناشــز ًا ال نفقــة لهــا وال ســكنى علــى زوجهــا جــاء يف‬\n      ‫املغنــي ‪ 4/11‬عنــد ذكــره ملــا يعــد نشــوز ًا مســقط ًا للنفقــة ‪ ( :‬وكذلــك‬\n      ‫إن انتقلــت مــن منزلــه بغيــر إذنــه ) وجــاء يف كشــاف القنــاع ‪138/13‬‬\n      ‫مــا نصــه ‪ ( :‬أو انتقلــت مــن منزلــه بغيــر إذنــه فــا نفقــة لهــا لنشــوزها ولــو‬\n      ‫كان خروجهــا مــن منزلــه يف غيبتــه بغيــر إذنــه فــا نفقــة ) لــذا فقــد‬\n      ‫حكمــت مبــا يلــي ‪ :‬أو ًال ‪ :‬رد دعــوى املدعيــة يف مطالبتهــا بالنفقــة للمــدة‬\n      ‫مــن تاريــخ خروجهــا مــن منــزل زوجهــا يف ‪1433/05/18‬ه ـ حتــى اآلن‬\n      ‫وذلــك لكونهــا خرجــت بطوعهــا واختيارهــا بــا ســبب شــرعي ‪ .‬ثاني ـاً‪:‬‬\n      ‫حكمــت علــى املدعــى عليــه بــأن يدفــع للمدعيــة نفقــة شــهرية البنــه‬\n      ‫‪ .........‬قدرهــا ســتمائة ريــال وتكــون هــذه النفقــة شــاملة لألشــهر التــي‬\n      ‫لــم يســلم فيهــا املدعــى عليــه النفقــة للمدعيــة مــن تاريــخ رفــع الدعــوى‬\n      ‫باحملكمــة يف تاريــخ ‪1433/11/27‬ه ـ إلقــراره بأنــه لــم يدفــع لهــا نفقــة‬\n      ‫ابنــه للمــدة املذكــورة ومبــا ذكــر كلــه حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعيــة واملدعــى عليــه قــرر كل واحــد منهمــا عــدم قناعتــه‬\n      ‫باحلكــم وطلــب االســتئناف فأفهمــا مبراجعــة احملكمــة يــوم األربعــاء‬\n      ‫‪1434/07/12‬ه ـ الســتالم نســخة احلكــم ومــن ثــم تقــدمي كل منهمــا‬\n      ‫الئحتــه االعتراضيــة عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ اســتالم كل‬\n\n\n‫‪217‬‬\n\f‫واحــد منهمــا نســخة احلكــم وإذا لــم يتقــدم بإعتراضــه خــال هــذه املــدة‬\n‫فــإن احلكــم يكتســب القطعيــة ففهمــا ذلــك وعليــه جــرى التوقيع وباهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                          ‫يف ‪1434/07/08‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫باخلــرج برقــم ‪ 332123722‬وتاريخ‪1434/8/14‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ......... /‬املســجل برقــم‬\n‫‪34270475‬وتاريــخ ‪1434/7/17‬ه ـ اخلــاص بدعــوى‪ ... /‬ســجل مدنــي‬\n‫رقــم ‪ ...‬ضــد ‪ .... /‬يف قضيــة نفقــة أوالد ‪ ........‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مباهــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪ ،‬واهلل‬\n        ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪218‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":212,"source_page_end":218,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c1921e7046bbba42c071bdadd393d51276a6443b67885d8f8da17fa5fd8ca5f7","normalized_text_hash":"f5c7e6f27ac0b656ff2f8941da7532ffbd09c72b7b806b5444a00b90e155280d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p212-34270475"},{"id":"df5ac9ae-a1f7-5fc9-bf63-ac4023cc74ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة ابنتها املاضية مع إقرارها بأنها لم تنو الرجوع على األب بالنفقة -صرف النظر عن الدعوى لعدم نية الرجوع يف النفقة.","document_number":"34266103","case_number":"33688333","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/11","year":"1434","subject":"نفقة -مطالبة أم بنفقة ابنتها املاضية مع إقرارها بأنها لم تنو الرجوع على األب بالنفقة -صرف النظر عن الدعوى لعدم نية الرجوع يف النفقة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/11/11 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34266103 :‬‬\n                          ‫َر ْق ُم الدعوى‪33688333 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34297008‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n\n       ‫نفقــة ‪ -‬مطالبــة أم بنفقــة ابنتهــا املاضيــة مــع إقرارهــا بأنهــا لــم تنــو‬\n       ‫الرجــوع علــى األب بالنفقــة ‪ -‬صــرف النظــر عــن الدعــوى لعــدم نيــة‬\n                                                          ‫الرجــوع يف النفقــة‪.‬‬\n\n\n\n\n       ‫مــا قــرره أهــل العلــم ومنهــم شــيخ اإلســام ابــن تيميــة يف مجمــوع‬\n       ‫الفتــاوى ج‪ 34‬ص ــ‪ 134‬أن األم إذا أنفقــت علــى ولدهــا ولــم تنــو الرجــوع‬\n                                                                ‫فليــس لهــا ذلــك‪.‬‬\n\n\n\n\n       ‫ادعــت املدعيــة ضــد املدعــى عليــه مطلقهــا أنهــا كانــت زوجتــه وقــد‬\n       ‫طلقهــا وأجنبــت منــه بنت ـ ًا واحــدة بتاريــخ ‪1399/8/25‬ه ـ وقــد طلقهــا‬\n       ‫بتاريــخ ‪1413‬ه ـ وأنــه لــم ينفــق علــى ابنتــه منــذ طالقهــا وأنهــا كانــت‬\n       ‫تنفــق عليهــا تبرع ـ ًا منهــا دون نيــة الرجــوع علــى املدعــى عليــه وطالبــت‬\n       ‫املدعيــة بنفقــة البنــت املاضيــة ‪ -‬أجــاب املدعــى عليــه باملصادقــة علــى‬\n       ‫الدعــوى وقــرر أنــه لــم ينفــق علــى البنــت ألن والدتهــا أخذتهــا ‪ -‬قــرر‬\n       ‫ـاء علــى إقــرار املدعيــة بأنهــا كانــت تنفــق تبرع ـ ًا‬\n                                                               ‫ناظــر القضيــة أنــه بنـ ً‬\n       ‫دون نيــة الرجــوع وملــا قــرره أهــل العلــم أن األم إذا أنفقــت ولــم تنــو الرجوع‬\n       ‫فليــس لهــا ذلــك فقــد صــدر احلكــم بــرد الدعــوى وإخــاء ســبيل املدعــى‬\n‫‪219‬‬\n\f‫عليــه منهــا ‪ -‬صــدر قــرار محكمــة االســتئناف باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33688333‬وتاريــخ‬\n‫‪1433/12/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332178732‬وتاريــخ‬\n‫‪1433/12/18‬هـ ففي يوم الثالثاء ‪1434/07/11‬هـ افتتحت اجللسة يف‬\n‫الســاعة الثامنــة والنصــف وفيهــا حضرت ‪........‬ســعودية اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم ‪........‬وادعــت علــى ‪........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪........‬قائلــة إن املدعــى عليــه كان زوجــا لــي وقــد‬\n‫طلقنــي وقــد أجنبــت منــه بنتــا اســمها ‪....‬املولــدة بتاريــخ ‪1399/08/25‬ه ـ‬\n‫وقــد طلقنــي عــام ‪1413‬ه ـ ولــم ينفــق عليهــا منــذ طالقــي وأنــا كنــت‬\n‫أنفــق عليهــا فأنــا موظفــة مــن قبــل أن أطلــق وأنــا لــم أكــن أنــو الرجــوع‬\n‫عليــه وكنــت أتبــرع بذلــك ولــم يكــن يهتــم بابنتــه أطلــب احلكــم لــي‬\n‫بنفقــة البنــت املاضيــة منــذ أن طلقنــي هكــذا ادعــت وبســؤال املدعــى‬\n‫عليــه اإلجابــة أجــاب قائــا مــا ذكرتــه املدعيــة صحيــح وأنــا لــم أنفــق‬\n‫عليهــا ألن والدتهــا قــد أخذتهــا وأطلــب رد دعواهــا وإخــاء ســبيلي مــن‬\n‫هــذه الدعــوى هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة‬\n‫والتــي تتضمــن طلبهــا نفقــة البنــت املاضيــة وأنهــا لــم تكــن تنــو الرجــوع‬\n‫علــى املدعــى عليــه وبنــاء علــى إجابــة املدعــى عليــه واملتضمنــة اإلقــرار‬\n‫وملــا أن املدعيــة لــم تنــو الرجــوع علــى املدعــى عليــه ملــا أنفقــت وقــد قــرر‬\n‫أهــل العلــم ومنهــم شــيخ اإلســام ابــن تيميــة يف مجمــوع الفتــاوى ج‪34‬ص‬\n                                                                                          ‫‪220‬‬\n\f      ‫‪ 134‬أن األم إذا أنفقــت علــى ابنتهــا ولــم تنــو الرجــوع فليــس لهــا ذلــك فلــم‬\n      ‫يثبــت لــدي أن للمدعيــة مطالبــة املدعــى عليــه بالنفقــة وعليــه فقــد رددت‬\n      ‫دعواهــا وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبــه حكمــت‬\n      ‫وبإعــان احلكــم علــى املدعيــة اعترضــت وطلبــت التمييــز واســتعدت‬\n      ‫بتقــدمي الئحــة اعتراضيــة فأفهمــت بــأن عليهــا مراجعــة احملكمــة يــوم‬\n      ‫األحــد ‪1434/07/16‬ه ـ الســتالم نســخة احلكــم وإذا فــات علــى ميعــاد‬\n      ‫االعتــراض ثالثــون يومــا ولــم تقــدم الئحتهــا االعتراضيــة ســقط حقهــا‬\n      ‫يف االعتــراض واكتســب احلكــم القطعيــة جــرى النطــق باحلكــم يف‬\n      ‫يــوم الثالثــاء ‪1434/07/11‬ه ـ الســاعة التاســعة‪ ،‬واختتمــت اجللســة يف‬\n      ‫الســاعة التاســعة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/11‬ه ـ‬\n      ‫احلمــد هلل وحــده بعــد ففــي يــوم األحــد ‪1434/07/16‬ه ـ افتتحت اجللســة‬\n      ‫يف الســاعة احلاديــة عشــرة والربــع وفيهــا حضــرت املدعيــة أصالــة ‪........‬‬\n      ‫املثبتــة هويتــه ســابقا واســتلمت نســخة احلكــم وأفهمــت بتعليمــات‬\n      ‫التمييــز كمــا يف اجللســة املاضيــة فتفهمــت ذلــك‪ ،‬واختتمــت اجللســة ثــم‬\n      ‫يف يــوم الثالثــاء ‪1434/07/25‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة‬\n      ‫عشــرة وفيهــا حضــرت املدعيــة أصالــة ‪........‬املثبتــة هويتهــا ســابقا‬\n      ‫وقدمــت الئحتهــا االعتراضيــة املقيــدة يف احملكمــة برقــم ‪341801405‬‬\n      ‫وتاريــخ ‪1434/07/25‬ه ـ واملكونــة مــن ورقــة واحــدة مبرفقاتهــا وعــدد‬\n      ‫مرفقاتهــا ســت ورقــات وباالطــاع عليهــا لــم أجــد بهــا مايؤثــر علــى مــا‬\n      ‫حكمــت بــه لــذا قــررت رفعهــا إلــى محكمــة االســتئناف مــع كامــل‬\n      ‫املعاملــة والصــك وصــورة مصدقــة مــن الضبــط‪ ،‬واختتمــت اجللســة يف‬\n      ‫الســاعة الثانيــة عشــرة والربــع‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى هلل علــى نبينــا‬\n\n\n‫‪221‬‬\n\f                ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر ‪1434/07/25‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ففــي يــوم اخلميــس ‪1434/09/02‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الواحــدة وخمــس وأربعــن دقيقــة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بالرقــم املقيــد يف احملكمــة ‪332178732‬‬\n‫وتاريــخ ‪1434/08/30‬ه ـ وبرفقهــا خطــاب فضيلــة رئيــس محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف ذو الرقــم ‪332178732‬‬\n‫والتاريــخ ‪1434/08/28‬ه ـ واملتضمــن‪ (:‬نفيدكــم أنــه جــرى تدقيــق‬\n‫احلكــم مــن الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصار وبيوت املال وصدر بشأنه القرار املرفق ذو الرقم ‪34297008‬‬\n‫وتاريــخ ‪1434/08/15‬ه ـ املــدون علــى ظهــر الصــك‪ ،‬نبعثــه لكــم مــع‬\n‫كامــل مشــفوعات املعاملــة إلكمــال الــازم واهلل يحفظكم‪).‬ا‪.‬ه ـ‬\n‫كمــا برفقهــا قــرار تصديــق رقــم ‪ 34297008‬وتاريــخ ‪1434/08/15‬ه ـ‬\n‫ونصــه‪ (:‬احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪،‬‬\n‫وبعــد‪ :‬نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع‬\n‫خطــاب رئيــس احملكمــة العامــة مبحافظــة جــدة رقــم ‪332178732‬‬\n‫وتاريــخ ‪1434/07/29‬ه ـ املشــتملة علــى الصــك رقــم ‪34266103‬‬\n‫وتاريــخ ‪1434/07/11‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n‫العامــة بجــدة الشــيخ‪........ /‬املتضمــن دعــوى ‪........‬ضــد ‪ ........‬يف نفقــة‬\n‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة‬\n‫علــى احلكــم‪ ،‬واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم‪ ،،،،،‬قاضــي اســتئناف ‪........‬توقيعــه وختمــه قاضــي‬\n\n\n                                                                                    ‫‪222‬‬\n\f      ‫اســتئناف ‪ ........‬توقيعــه وختمــه رئيــس الدائــرة ‪........‬توقيعــه وختمــه)‬\n      ‫ا‪.‬ه ـ لــذا جــرى إحلاقــه‪ ،‬واختتمــت اجللســة يف الســاعة الثانيــة والربــع‪،‬‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                 ‫‪1434/09/02‬ه ـ‬\n\n\n\n\n‫‪223‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":219,"source_page_end":223,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93994c6fcc0fb6de944d2e109c3d0e0203e01f5fc2404cd90e8518bc53699cb2","normalized_text_hash":"ac0d4b718ffa35d223c924ee8738007833cbc817a2144a1f51692debdb4028d5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p219-34266103"},{"id":"ab6b245d-ac94-5833-845e-5a22cfa378e3","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة ابنتها -مطالبة زوجة بنفقة عدتها - تقدير نفقة من قبل هيئة النظر -احلكم بنفقة أكثر مما طالبت به املدعية -احلكم مبا اصطلح عليه الطرفان يف نفقة العدة - احلكم على املدعى عليه بدفع نفقة ابنته -تضمن حكم النفقة بالنفاذ املعجل .","document_number":"34183664","case_number":"33698622","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف من قبله بنظر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/9","year":"1434","subject":"نفقة -مطالبة أم بنفقة ابنتها -مطالبة زوجة بنفقة عدتها - تقدير نفقة من قبل هيئة النظر -احلكم بنفقة أكثر مما طالبت به املدعية -احلكم مبا اصطلح عليه الطرفان يف نفقة العدة - احلكم على املدعى عليه بدفع نفقة ابنته -تضمن حكم النفقة بالنفاذ املعجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/9 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34183664 :‬‬\n                   ‫َر ْق ُم الدعوى‪33698622 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34320983‬تاريخه‪1434/9/16 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة أم بنفقــة ابنتهــا ‪ -‬مطالبــة زوجــة بنفقــة عدتهــا ‪-‬‬\n‫تقديــر نفقــة مــن قبــل هيئــة النظــر ‪ -‬احلكــم بنفقــة أكثــر ممــا طالبــت‬\n‫بــه املدعيــة ‪ -‬احلكــم مبــا اصطلــح عليــه الطرفــان يف نفقــة العــدة ‪-‬‬\n‫احلكــم علــى املدعــى عليــه بدفــع نفقــة ابنتــه ‪ -‬تضمــن حكــم النفقــة‬\n                                                           ‫بالنفــاذ املعجــل ‪.‬‬\n\n\n\n\n         ‫‪ .1‬املادة ‪ 2/199‬من نظام املرافعات الشرعية والئحته التنفيذية‬\n‫‪ .2‬الفقــرة الثانيــة مــن املــادة ‪ 192‬مــن الالئحــة التنفيذيــة لنظام املرافعات‬\n‫الشــرعية حيــث جــاء فيهــا ( للمحكمــة أن حتكــم بشــيء لــم يطلبــه‬\n‫اخلصــوم أو بأكثــر ممــا طلبــوه إذا ظهــر لهــا مــا يبــرر ذلــك كحــق عــام‬\n                                                                ‫أو حــق قاصــر)‬\n                              ‫‪ .3‬املادة (‪ )178‬من نظام املرافعات الشرعية‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا وطلقهــا الطلقــة‬\n‫الثانيــة وأجنبــت لــه علــى فــراش الزوجيــة بنت ـ ًا واحــدة وطالبــت املدعيــة‬\n‫إلــزام املدعــى عليــه بنفقــة البنــت مبلغـ ًا قــدره ألــف ريــال ونفقــة عدتهــا ‪-‬‬\n‫أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أنــه يكفــي البنــت‬\n                                                                                         ‫‪224‬‬\n\f      ‫مبلــغ خمســمائة ريــال وغيــر مســتعد مبــا زاد علــى هــذا املبلــغ ‪ -‬مت تقديــر‬\n      ‫نفقــة البنــت مــن مكتــب الصلــح مبلغـ ًا قــدره ألف ومائة ريــال ومت الصلح‬\n      ‫علــى نفقــة العــدة ثالثــة آالف ريــال ‪ -‬قررت املدعيــة موافقتها على تقدير‬\n      ‫مكتــب الصلــح وقــرر املدعــى عليــه املعارضــة وتصادقــا علــى صلــح نفقة‬\n      ‫العــدة قــرر ناظــر القضيــة إمضــاء صلــح نفقــة العــدة مبلغ ـ ًا قــدره ثالثــة‬\n      ‫آالف ريــال وإلــزام املدعــى عليــه بــأن يســلم املدعيــة نفقــة البنــت ألــف‬\n      ‫ومائــة ريــال وتضمــن احلكــم بالنفــاذ املعجــل وفقـ ًا للمــادة (‪ )2/199‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ‪ -‬قــررت املدعيــة القناعــة وقــرر املدعــى عليــه‬\n                         ‫عــدم القناعــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬املــازم القضائــي لــدى الشــيخ‬\n      ‫القاضــي يف احملكمــة العامــة بالريــاض واملكلــف مــن قبلــه بنظــر‬\n      ‫الدعــوى وبنــاء علــى املعاملــة احملالــة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 33698622‬وتاريــخ ‪ 1433/12/22‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332219366‬وتاريــخ ‪ 1433/12/22‬ه ـ ففــي‬\n      ‫يــوم األربعــاء املوافــق‪ 1434/02/06‬ه ـ حضــرت (‪ ).....‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم(‪ ).....‬واملعــرف بهــا مــن قبــل أخيهــا احلاضــر‬\n      ‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).....‬وادعــت علــى‬\n      ‫احلاضــر معهــا (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪).....‬‬\n      ‫وبســؤال املدعيــة عــن حتريــر دعواهــا قــررت قائلــة إن املدعــى عليــه‬\n      ‫زوجــي تزوجنــي مبوجــب عقــد النــكاح رقــم (‪ )......‬يف ‪1432/10/30‬ه ـ‬\n      ‫وطلقنــي الطلقــة الثانيــة مبوجــب صــك إثبــات الطــاق الصــادر مــن‬\n\n‫‪225‬‬\n\f‫محكمة األحوال الشــخصية بالرياض برقم ‪.........‬يف ‪1433/12/21‬هـ‬\n‫وأجنبــت لــه علــى فــراش الزوجيــة البنــت املولــودة بتاريــخ ‪1433/10/9‬ه ـ‬\n‫وأطلــب إلــزام املدعــى عليــه بتســليم النفقــة الكافيــة للبنــت وقدرهــا‬\n‫ألــف ريــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه قــال‬\n‫ماذكرتــه املدعيــة مــن الــزواج والطــاق والبنــت كلــه صحيــح والــذي‬\n‫يكفيهــا مــن النفقــة خمســمائة ريــال شــهري ًا وأنــا غيــر مســتعد مبــا زاد‬\n‫عــن هــذا هكــذا أجــاب وعليــه قــررت الكتابــة ملكتــب الصلــح لتقريــر‬\n‫النفقــة الكافيــة للبنــت ورفعــت اجللســة حتــى يــوم األربعــاء املوافــق‬\n‫‪1434/3/4‬ه ـ ويف يــوم األربعــاء املوافــق ‪1434/3/4‬ه ـ لــدي أنــا (‪).....‬‬\n‫القاضــي باحملكمــة العامــة بالريــاض حضــرت املدعيــة برفقــة معرفهــا‬\n‫املدونــة بياناتــه يف اجللســة الســابقة وحضــر املدعــى عليــه وانصــرف قبــل‬\n‫فتــح اجللســة وقــد جــرت الكتابــة منــا إلــى مكتــب الصلــح باخلطــاب‬\n‫رقــم ‪ 34328390‬يف ‪1434/2/9‬ه ـ بتحديــد نفقــة البنــت ولــم تردنــا‬\n‫إفــادة وقــررت املدعيــة أن املعاملــة الزالــت يف قســم الصلــح قيــد اإلجــراء‬\n‫وأطلــب مخاطبــة مكتــب الصلــح لتحديــد نفقتــي أثنــاء العــدة وأجــرة‬\n‫الرضــاع واحلضانــة هكــذا قــررت وعليــه رفعــت اجللســة حلــن ورود‬\n‫املعاملــة مــن مكتــب الصلــح ويف يــوم الثالثــاء املوافــق ‪1434/4/9‬ه ـ‬\n‫لــدي أنــا املــازم القضائــي املكلــف بعمــل املكتــب القضائــي الثامــن‬\n‫مبوجــب خطــاب فضيلــة رئيــس احملكمــة املســاعد بالقيــام بأعمــال‬\n‫مكتــب فضيلــة الشــيخ برقــم ‪ 34697008‬يف ‪1434/3/21‬ه ـ حضــرت‬\n‫املدعيــة واملعــرف بهــا مــن قبــل املدعــى عليــه احلاضــر وبعــرض ماســبق‬\n‫ضبطــه علــى املدعيــة صادقــت عليــه وقــد وردنــا قــرار مكتــب الصلــح‬\n                                        ‫رقــم ‪ 34/572250‬يف ‪1434/4/6‬ه ـ‬\n\n\n                                                                                    ‫‪226‬‬\n\f      ‫واملتضمــن نــص احلاجــة منــه (نفيــد فضيلتكــم أنــه مت االجتمــاع‬\n      ‫بالطرفــن وجــرى عــرض الصلــح عليهمــا فاصطلحــا وهلل احلمــد علــى أن‬\n      ‫تكــون النفقــة عــن العــدة ‪ 3000‬ريــال وذلــك حســب إقرارهمــا املرفــق‬\n      ‫لــذا ولقــول اهلل تعالــى ( والصلــح خيــر) وقــول النبــي صلــى اهلل عليــه‬\n      ‫وســلم ( الصلــح جائــز بــن املســلمني ) فإننــا نــرى إمضــاء مــا اصطلحــا‬\n      ‫عليــه هــذا مالدينــا واهلل يحفظكــم أعضــاء مكتــب الصلــح توقيعــه‬\n      ‫توقيعــه ومصادقــة مديــر مكتــب الصلــح توقيعــه) كمــا وردنــا تقريــر‬\n      ‫مكتب الصلح رقم ‪ 173‬يف ‪1434/3/10‬هـ واملتضمن نص احلاجة منه‬\n      ‫(نفيــد فضيلتكــم أنــه باالجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا‬\n      ‫بخصــوص تقديــر النفقــة حيــث ذكــرت املدعيــة بأنهــا تطالــب بنفقــة‬\n      ‫ابنتهــا املذكــورة وأن نفقتهــا تكلفهــا أكثــر مــن ‪ 1000‬ريــال وكذلــك‬\n      ‫مصاريــف العــاج أمــا بالنســبة للمدعــى عليــه فقــد ذكــر بأنــه ليس لديه‬\n      ‫مانــع مــن النفقــة علــى ابنتــه بواقــع ‪ 500‬ريــال شــهري ًا أســوة ببقيــة إخوتهــا‬\n      ‫ال منهمــا‬\n               ‫وذلــك لكونــه يوجــد عليــه التزامــات ماليــه وجتــدون إقــرار ك ً‬\n      ‫ـاء علــى ذلــك واحلــال كمــا ذكــر وبعــد االطــاع علــى‬     ‫بطــي املعاملــة وبنـ ً‬\n      ‫مقــدار مرتــب املدعــى عليــه حيــث اتضــح أنــه يتقاضــى مرتــب وقــدره‬\n      ‫‪ 29238‬ريــا ًال ويوجــد عليــه أقســاط شــهرية مبعــدل ‪ 10600‬ريــال وذلــك‬\n      ‫حســب كشــف احلســاب املرفــق فإننــا نــرى أن تكــون النفقــة املســتقبلية‬\n      ‫البنــة املدعيــة ‪ 1100‬ريــال هــذا مــا لدينــا واهلل يحفظكــم أعضــاء‬\n      ‫مكتــب الصلــح توقيعــه ومصادقــة مديــر مكتــب الصلــح توقيعــه)‬\n      ‫وبعــرض ذلــك علــى أطــراف الدعــوى صادقــا علــى الصلــح بخصــوص‬\n      ‫النفقــة عــن مــدة العــدة وقدرهــا ثالثــة آالف ريــال ووافقــت املدعيــة علــى‬\n      ‫ماقــرره مكتــب الصلــح بخصــوص النفقــة املســتقبلية للبنــت واعتــرض‬\n\n\n‫‪227‬‬\n\f‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وألن الطرفــن‬      ‫املدعــى عليــه فبنـ ً‬\n‫اصطلحــا علــى نفقــة املدعيــة مــدة العــدة مببلــغ وقــدره ثالثــة آالف ريــال‬\n‫وملــا قــرره أهــل اخلبــرة مــن نفقــة البنــت(وألن احلــق واحلكــم يف حقيقتــه‬\n‫هــو للبنــت القاصــرة وال حــرج حينئــذ يف احلكــم للمدعــي بأكثــر ممــا‬\n‫طلــب وهــو صريــح مــا جــاءت بــه الفقــرة الثانيــة للمــادة ‪ 192‬مــن الالئحــة‬\n‫التنفيذيــة لنظــام املرافعــات الشــرعية حيــث جــاء فيهــا ( للمحكمــة أن‬\n‫حتكــم بشــيء لــم يطلبــه اخلصــوم أو بأكثــر ممــا طلبــوه إذا ظهــر لهــا‬\n‫مــا يبــرر ذلــك كحــق عــام أو حــق قاصــر ‪ ) ...‬لــذا فقــد ثبــت لــدي مــا‬\n‫اصطلــح عليــه الطرفــان وحكمــت علــى املدعــى عليــه أن يســلم للمدعيــة‬\n‫ثالثــة آالف ريــال مقابــل نفقــة العــدة كمــا حكمــت علــى املدعــى عليــه‬\n‫أن يســلم للمدعيــة النفقــة املســتقبلية للبنــت وقدرهــا ألــف ومائــة ريــال‬\n‫شــهري ًا وهــذا احلكــم مشــمول بالنفــاذ املعجــل وفق ـ ًا للمــادة (‪)2/199‬‬\n‫مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة وبعــرض احلكــم علــى‬\n‫أطــراف الدعــوى قنعــت املدعيــة ولــم يقنــع املدعــى عليــه وطلــب متكينــه‬\n‫مــن االســتئناف بالئحــة اعتراضيــة فأجيــب لطلبــه وجــرى تســليمه‬\n‫صــورة لنســخة احلكــم حــا ًال وأفهــم بــأن عليــه تقــدمي اعتراضــه خــال‬\n‫ثالثــن يومـ ًا مــن تاريــخ االســتالم وإذا مضــت املــدة احملــددة لالعتــراض‬\n‫ولــم يقــدم الئحتــه ســقط حقــه يف االعتــراض واكتســب احلكــم الصفــة‬\n‫القطعيــة طبقـ ًا للمــادة (‪ )178‬مــن نظــام املرافعــات الشــرعية وصلــى اهلل‬\n                           ‫وســلم علــى نبينــا محمــد حــرر يف ‪1434/4/9‬ه ـ‬\n‫(وألن احلــق واحلكــم يف حقيقتــه هــو للبنــت القاصــرة وال حــرج حينئــذ يف‬\n‫احلكــم للمدعــي بأكثــر ممــا طلــب وهــو صريــح مــا جــاءت بــه الفقــرة‬\n‫الثانيــة للمــادة ‪ 192‬مــن الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية‬\n\n\n                                                                                        ‫‪228‬‬\n\f      ‫حيــث جــاء فيهــا ( للمحكمــة أن حتكــم بشــيء لــم يطلبــه اخلصــوم‬\n      ‫أو بأكثــر ممــا طلبــوه إذا ظهــر لهــا مــا يبــرر ذلــك كحــق عــام أو حــق‬\n                                                                            ‫قاصــر ‪) ...‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنني املوافق ‪1434/10/26‬هـ افتتحت‬\n      ‫اجللســة الســاعة التاســعة والنصــف صباح ـ ًا لــدي أنــا ‪ .......‬القاضــي‬\n      ‫يف احملكمــة العامــة بالريــاض حيــث أن ناظــر الدعــوى الشــيخ ‪.......‬‬\n      ‫قــد انتقــل للعمــل خــارج املكتــب وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف مــزودة بقرارهــا رقــم ‪ 34320983‬وتاريــخ ‪1434/9/16‬ه ـ‬\n      ‫واملتضمــن املصادقــة علــى احلكــم وللبيــان حــرر ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬حــرر يف ‪ 1434/10/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض برقــم ‪ 341727088‬وتاريــخ ‪1434/9/7‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪).....(/‬‬\n      ‫املســجل برقــم ‪ 34183664‬وتاريــخ ‪1434/4/9‬ه ـ اخلــاص بدعــوى(‪).....‬‬\n      ‫ســجل مدنــي رقــم(‪ ).....‬ضــد‪ ).....(/‬ســجل مدنــي رقــم(‪ ).....‬يف قضيــة‬\n      ‫نفقــة ‪ .‬وقــد تضمــن الصــك حكــم فضيلتــه مباهــو مــدون ومفصــل فيــه‬\n      ‫‪ .‬وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n      ‫بالصــك بنــاء علــى قرارنــا رقــم ‪ 34281886‬وتاريــخ ‪1434/7/29‬ه ـ‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم بعــد اجلــواب األخيــر ‪ ،‬واهلل املوفــق‬\n                     ‫وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪229‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":224,"source_page_end":229,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7938e57bd08a8ec4a8c11a438b25e7d8077155a83046a4457133f56e470fa53","normalized_text_hash":"2d4ece4b98e4c926336bdca47248d09e1206219b5ecc28bbdc60ada3a4605616","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p224-34183664"},{"id":"f5ab6ef8-480c-5c74-9202-2a07e07a26ba","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقتها وبخادمة -تقسيم نفقة قريب على من جتب عليه ممن يرث القريب من املقتدرين على حسب امليراث الشرعي -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األوالد بدفع نفقة شهرية لأم وأجرة املواصات -حكم على أوالد بوجوب خدمة والدتهم بأنفسهم فإن لم يستطيعوا فعليهم أن يوفروا من يقوم بخدمتها -اإلفهام مبطالبة من جتب عليه النفقة بحصته الواجبة عليه.","document_number":"34283903","case_number":"34140521","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف ففي هذا اليوم األحد 1434/05/26ه ويف متام الساعة التاسعة صباحا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"نفقة -مطالبة أم بنفقتها وبخادمة -تقسيم نفقة قريب على من جتب عليه ممن يرث القريب من املقتدرين على حسب امليراث الشرعي -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األوالد بدفع نفقة شهرية لأم وأجرة املواصات -حكم على أوالد بوجوب خدمة والدتهم بأنفسهم فإن لم يستطيعوا فعليهم أن يوفروا من يقوم بخدمتها -اإلفهام مبطالبة من جتب عليه النفقة بحصته الواجبة عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/30 :‬هـ‬\n                       ‫ُ‬                  ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪34283903 :‬‬\n                           ‫َر ْق ُم الدعوى‪34140521 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34357857‬تاريخه‪1434/11/11 :‬هـ‬\n\n\n\n        ‫نفقــة ‪ -‬مطالبــة أم بنفقتهــا وبخادمــة ‪ -‬تقســيم نفقــة قريــب علــى‬\n        ‫مــن جتــب عليــه ممــن يــرث القريــب مــن املقتدريــن علــى حســب امليــراث‬\n        ‫الشــرعي ‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء ‪ -‬احلكــم علــى‬\n        ‫األوالد بدفــع نفقــة شــهرية لــأم وأجــرة املواصــات ‪ -‬حكــم علــى‬\n        ‫أوالد بوجــوب خدمــة والدتهــم بأنفســهم فــإن لــم يســتطيعوا فعليهــم‬\n        ‫أن يوفــروا مــن يقــوم بخدمتهــا ‪ -‬اإلفهــام مبطالبــة مــن جتــب عليــه‬\n                                                ‫النفقــة بحصتــه الواجبــة عليــه‪.‬‬\n\n\n\n\n        ‫جــاء يف كشــاف القنــاع (ويلزمــه أي املنفــق خدمــة قريــب وجبــت نفقته‬\n                                 ‫فيخدمــه بنفســه أو غيــره حلاجــة إلــى خدمة)‬\n\n\n\n\n        ‫ادعــت أم علــى ابنــن مــن أوالدهــا إنهــا امــرأة كبيــرة مقعــدة وســاكنه‬\n        ‫لوحدهــا يف بيــت أعطاهــا إيــاه أحــد احملســنني لتمكــث فيــه طــوال‬\n        ‫حياتهــا وأنهــا بحاجــة إلــى مصــروف شــهري وخادمــة تقــوم بخدمتهــا‬\n        ‫وطلبــت إلــزام ابنيهــا املدعــى عليهمــا بذلــك ‪ -‬أجــاب املدعــى عليــه‬\n        ‫األول بــأن الدعــوى غيــر صحيحــة وان املدعيــة ســاكنة يف نفــس البيــت‬\n        ‫الــذي يســكن فيــه املدعــى عليــه الثانــي ولهــا جنــاح مســتقل ولكنهــا ال‬\n\n‫‪237‬‬\n\f‫جتلــس فيــه وان أوالدهــا يطالبونهــا بــأن جتلــس عندهــم ولكنهــا ترفض‬\n‫وانهــم مســتعدون خلدمتهــا ‪ -‬أجــاب املدعــى عليــه الثانــي أنهــا رفعــت هــذه‬\n‫الدعــوى عليهمــا دون ابنهــا الثالــث وانــه ســبق أن رعــى والدتــه وهــي‬\n‫ســاكنه معــه وهــو يخدمهــا مــع زوجتــه وال يوافــق علــى اســتقدام خادمــة‬\n‫لعــدم قدرتــه علــى ذلــك ‪ -‬قــررت املدعيــة أن عــدد أبنائهــا الذكــور ثالثــة‬\n‫واإلنــاث ســت وأن املقتــدر مالي ـ ًا أوالدهــا الذكــور دون اإلنــاث ‪ -‬قــرر‬\n‫قســم اخلبــراء باحملكمــة حاجــة املدعيــة إلــى نفقــة شــهرية قدرهــا ألــف‬\n‫وســتمائة ريــال دون راتــب اخلادمــة املنزليــة ‪ -‬وحاجتهــا خلادمــة منزليــة‬\n‫‪ -‬وأجــرة مواصــات خمســمائة ريــال شــهريا ‪ -‬قنعــت املدعيــة بتقديــر‬\n‫قســم اخلبــراء وقــرر املدعــى عليهمــا اعتراضهمــا علــى القــرار ‪ -‬بنــاء‬\n‫علــى مــا تقــدم قــرر ناظــر القضيــة أن املقتــدر مــن أوالدهــا الذكــور هــم‬\n‫ثالثــة وأنهــا رفعــت علــى اثنــن فقــط وان الواجــب علــى كل واحــد مــن‬\n‫األوالد الذكــور بعــد قســمة حاجــة املدعيــة بينهــم هــو ســبعمائة ريــال‬\n‫الن نفقــة األقــارب جتــب عليهــم علــى حســب ميراثهــم الشــرعي دون‬\n‫غيرهــم لــذا ولألســباب املذكــورة باحلكــم فقــد صــدر احلكــم علــى‬\n‫املدعــى عليهمــا بــأن يدفــع كل واحــد منهمــا شــهريا ســبعمائة ريــال‬\n‫وإفهامهــا بوجــوب خدمــة والدتهمــا بأنفســهما فــإن لــم يســتطيعا فعليهمــا‬\n‫أن يوفــرا لوالدتهمــا مــن يقــوم بخدمتهــا وصــرف النظــر عــن مطالبــة األم‬\n‫بتوفيــر خادمــة لعــدم وجــود الزم حيــث تعهــد املدعــى عليهمــا بــأن يقومــا‬\n‫بذلــك ومت إفهــام املدعيــة بــان لهــا مطالبــة ابنهــا الثالــث متــى مــا أرادت‬\n‫بحصتــه مــن النفقــة ‪ -‬قــررت املدعيــة القناعــة وقــرر املدعــى عليهمــا‬\n‫عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة‬\n                                         ‫باملصادقــة علــى احلكــم باألكثريــة‪.‬‬\n\n\n                                                                                      ‫‪238‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي باحملكمــة العامــة‬\n      ‫بالطائــف ففــي هــذا اليــوم األحــد ‪1434/05/26‬ه ـ ويف متــام الســاعة‬\n      ‫التاســعة صباحا افتتحت اجللســة بناء على املعاملة احملالة لنا من فضيلة‬\n      ‫الرئيــس برقــم ‪ 34140521‬يف ‪1434/03/24‬ه ـ واملقيــدة باحملكمــة‬\n      ‫برقــم ‪ 34746114‬وفيهــا حضــرت ‪ .......‬املــرأة ســعودية بالســجل رقــم‬\n      ‫‪ .......‬واملعــرف بهــا مــن قبــل املدعــى عليهمــا ولديهــا احلاضريــن معهــا‬\n      ‫‪ .......‬ســعودي بالســجل املدنــي رقــم ‪ .......‬و ‪ .......‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪ .......‬وادعــت املــرأة قائلــة يف حتريــر دعواهــا إن هــؤالء احلاضريــن‬\n      ‫ولــدي وأنــا امــرأة كبيــرة مقعــدة ســاكنة لوحــدي يف حــي ‪.......‬يف بيــت‬\n      ‫أعطتنــي إيــاه‪ ...‬ألســكن فيــه طــول حياتــي وأنــا بحاجــة ملصروف شــهري‬\n      ‫وخادمــة تقــوم بخدمتــي أطلــب إلــزام ولــدي بذلــك هــذه دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليهمــا أجــاب ‪.......‬قائــا بــأن هــذه الدعــوى غيــر‬\n      ‫صحيحــة فأمــي ســاكنة بنفــس البيــت الــذي ســاكن فيــه أخــي ولهــا‬\n      ‫جنــاح مســتقل ولكــن هــي الجتلــس فيــه ونحــن أوالدهــا ثالثــة رجــال‬\n      ‫وســتة بنــات كل واحــد منــا يطالبهــا بجلوســها عنــده طــول وقــت حياتهــا‬\n      ‫لكنهــا ترفــض ذلــك ونحــن مســتعدون خلدمتهــا وأن نقــوم بكامــل‬\n      ‫طلباتهــا وأن نقدمهــا علــى أوالدنــا يف بيوتنــا وأنــا ال أوافــق علــى طلبهــا‬\n      ‫هــذه إجابتــي وأجــاب املدعــى عليــه ‪.......‬قائــا يف إجابتــه أنــا اســتغرب‬\n      ‫دعــوى الوالــدة علينــا فأنــا رفعــت ‪ ...‬الدعــوى دون أخــي وشــقيقي ‪.......‬‬\n      ‫بحجــة أن أخــي قــد قــام بهــا واســتقدم لهــا ســابقا خادمــة ورعــى شــؤونها‬\n      ‫ملــدة ســنتني فأنــا أيضــا قــد ســبق لــي ذلــك ملــدة ثــاث ســنوات ثــم قــام‬\n\n‫‪239‬‬\n\f‫أخــي ‪ ...‬بعــد ذلــك بالقيــام بشــؤونها بعــدي ملــدة ســنتني وأنــا لــم أقصــر‬\n‫معهــا وزوجتــي بنــت أختهــا وهــي اآلن ســاكنة معــي يف بيــت واحــد‬\n‫والبيــت الــذي تذكــره ملحــق لنفــس البيــت الــذي اســكن فيــه وأنــا لــن‬\n‫أقصــر عليهــا يف النفقــة إذا كانــت معــي يف البيــت تــأكل وتشــرب ممــا‬\n‫أشــرب واخلادمــة أنــا أخدمهــا وزوجتــي يف مقــام ابنتهــا تخدمهــا بنفســها‬\n‫ولــن أوافقهــا علــى اســتقدام خادمــة لعــدم اســتطاعتي املاديــة علــى ذلــك‬\n‫هــذه إجابتــي وكنــا قــد كتبنــا لرئيــس قســم الصلــح بكتابنــا رقــم‬\n‫‪ 34746114‬يف ‪1434/04/17‬ه ـ حملاولــة اإلصــاح بــن األم وأوالدهــا‬\n‫فوردنــا خطــاب رئيــس قســم اإلصــاح والتحكيــم باحملكمــة برقــم‬\n‫‪ 34746114‬يف ‪1434/04/30‬ه ـ وبرفقــه القــرار رقــم ‪/170‬ص يف‬\n‫‪1434/04/28‬ه ـ واملتضمــن بعــد املقدمــة مايلــي وبعــرض الصلــح بــن‬\n‫الطرفــن تعــذر الصلــح بينهمــا وبســؤال كل منهمــا عــن راتبــه أفــاد‬\n‫بأنــه يتقاضــى راتــب وقــدره ثمانيــة األف ريــال و‪ .......‬يتقاضــى راتــب‬\n‫وقــدره تســعة األف وأربعمائــة وتســعة وتســعون ريــال حســب افادتهمــا‬\n‫املرفقــة عليــه تــرى اللجنــة والــرأي لفضيلتكــم ان تكــون نفقــة املدعيــة‬\n‫كالتالــي أوال كل ابــن يدفــع ثمامنائــة ريــال ليصبــح مجمــوع املبلــغ ألــف‬\n‫وســتمائة ريــال كل شــهر نفقــة لوالدتهــم ثانيــا أن يســتقدم املدعــى‬\n‫عليهمــا لوالدتهمــا خادمــة وتكــون تكاليفهــا ورواتبهــا باملناصفــة بــن‬\n                                ‫األخويــن ولضيــق الوقــت جــرى رفــع اجللســة‬\n‫ويف جلســة أخــرى افتتحــت اجللســة وفيهــا حضــرت املدعيــة املعــرف بهــا‬\n‫مــن قبــل ابنهــا املدعــي عليــه ويف هــذه اجللســة جــرى ســؤال املدعيــة عــن‬\n‫أوالدهــا كــم عددهــم ومــا أســمائهم فأجابــت قائلــه عــدد الذكــور‬\n‫ثــاث أبنــاء وعــدد اإلنــاث ســتة بنــات فجــرى ســؤالها عــن قــدرة بقيــة‬\n\n\n                                                                                     ‫‪240‬‬\n\f      ‫األوالد املاليــة غيــر املدعــى عليهمــا فأجابــت بــأن أبنائــي الثالثة الذكور‬\n      ‫يشــتغلون ولديهــم رواتــب شــهرية وأمــا البنــات فليــس منهن واحده تشــتغل‬\n      ‫ولهــا راتــب وجميعهــم متزوجــات وعنــد أزواجهــن وليــس لهــم دخــل مالــي‬\n      ‫ويعتمــدون بعــد اهلل ســبحانه وتعالــى علــى أزواجهــن يف نفقتهــم ونحــو‬\n      ‫ذلــك بنــاء عليــه وحيــث لــم يحــدد بقــرار قســم الصلــح قــدر حاجــة املدعية‬\n      ‫للنفقــه الشــهرية بعــد ســؤالها عــن دخلهــا قــررت الكتابــة لهــم إلفادتنــا‬\n      ‫عــن ذلــك وقــد حــدد لهــم موعــد يف قســم الصلــح وحــدد موعــد لــدى‬\n                                                                              ‫مكتبنــا‬\n      ‫ويف جلســة أخــرى يف يــوم األربعــاء املوافــق‪ 1434/07/26‬ه ـ افتتحــت‬\n      ‫اجللســة وفيهــا حضــرت املدعيــة ســعوديه اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم واملعــرف بهــا مــن قبــل املدعــى عليهــم أوالدهــا احلاضريــن‬\n      ‫معهــا وعــادت املعاملــة مــن قســم اإلصــاح بخطابهــم رقــم ‪34746114‬‬\n      ‫يف ‪1434/7/25‬ه ـ وبرفقــه القــرار رقــم ‪/330‬ص يف ‪1434/7/23‬ه ـ‬\n      ‫والتضمــن بعــد املقدمــة انــه جــري االجتمــاع مــع طــريف الدعــوى يــوم‬\n           ‫‪1434/7/23‬ه ـ وتــرى اللجنــة أن تكــون نفقــة املدعيــة كالتالــي‪:‬‬\n      ‫(‪ )1‬حتتــاج املدعيــة نفقــة شــهريه وقدرهــا ألــف وســتمائة ريال كل شــهر‬\n                                                       ‫بــدون راتــب العاملــة املنزلية‪.‬‬\n                                 ‫(‪ )2‬حتتاج املدعية لعاملة منزليه تقوم برعايتها‪.‬‬\n      ‫(‪ )3‬حتتــاج املدعيــة ألجــرة مواصــات وقدرهــا خمســمائة ريــال كل‬\n      ‫شــهر وبــاهلل التوفيــق أه ـ فجــرى عرضــه علــى املدعيــة فأجابــت قائلــة‬\n      ‫الــذي يحكــم لــي بشــرع اهلل فأنــا راضيــة بــه وبعرضــه علــى املدعــى‬\n      ‫عليهمــا فأجــاب املدعــى عليــه بأننــي معتــرض علــى هــذا القــرار حيــث‬\n      ‫لــم يســأل عــن التزاماتــي ولــم يأخــذوا معلومــات منــي وأجــاب املدعــي‬\n\n\n‫‪241‬‬\n\f‫عليــه بأننــي اعتــرض علــى هــذا القــرار حيــث إن لــدي التزامــات ماليــه‬\n‫ال تســمح بتنفيــذه حيــث جــرى ســؤال املدعــي عليهــم أن والدتكــم يف‬\n‫اجللســة املاضيــة بــأن لديهــا ثالثــة أبنــاء وســتة بنــات وأن املقتــدر مــن‬\n‫أوالدي هــم الذكــور فقــط مــا تقولــون بذلــك فأجــاب كل واحــد منهمــا‬\n‫بــأن ذلــك صحيــح فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n‫جــري محاولــة اإلصــاح بــن املتداعيــن أكثــر مــن مــرة فتعــذر ذلــك‬\n‫وحيــث إن املدعيــة تطالــب املدعــى عليهمــا بنفقــه شــهريه وخادمــه‬\n‫وحيــث إن املقتدريــن مــن أوالد املدعيــة هــم أبنائهــا الذكــور فقــط وهــم‬\n‫ثالثــة كمــا جــاء يف كالم املدعيــة ومصادقــة املدعــى عليهمــا علــى ذلك‬\n‫وحيــث قــدرت جلنــة الصلــح باحملكمــة حاجــة املدعيــة للنفقــة الشــهرية‬\n‫بألــف وســتمائة ريــال شــهريا وخمســمائة ريــال أجــرة للمواصــات كل‬\n‫شــهر مبــا مجموعــه ألفــان ومائــه ريــال وحيــث إن املدعيــة قــد رفعــت‬\n‫دعواهــا علــى املدعــى عليهمــا دون أخيهمــا ‪.......‬وحيــث إن الواجــب علــى‬\n‫كل واحــد مــن األوالد الذكــور بعــد قســمة حاجــة املدعيــة بينهــم هــو‬\n‫ســبعمائة ريــال والن نفقــة األقــارب جتــب عليهــم علــى حســب ميراثهــم‬\n‫الشــرعي دون غيــره والن املقتدريــن ممــن يــرث املدعيــة هــم ثالثــة مــن‬\n‫أوالدهــا الذكــور والن الواجــب علــى املدعــى عليهــم هــو خدمــة أمهــم‬\n‫والقيام بشؤنها بأنفسهم جاء يف كشاف القناع‪ ( ( :‬ويلزمه) أي املنفق‬\n‫(خدمــة قريــب ) وجبــت نفقتــه فيخدمــه ( بنفســه أو غيــره حلاجــة ) إلــي‬\n‫اخلدمــة )‪ .‬لذلــك كلــه فقــد حكمــت علــى املدعــي عليهمــا بــأن يدفــع‬\n‫كل واحــد منهمــا لوالدتــه شــهريا ســبعمائة ريــال وأفهمتهمــا بوجــوب‬\n‫خدمــة والدتهــم بأنفســهم فــإن لــم يســتطيعوا ذلــك فعليهــم أن يوفــروا‬\n‫مــن يقــوم بخدمتهــا وصرفــت النظــر عــن طلــب املدعيــة إلــزام املدعــي‬\n\n\n                                                                                    ‫‪242‬‬\n\f      ‫عليهــم بتوفيــر خادمــة لعــدم وجــود الزمــه حيــث تعهــد املدعــى عليهمــا ان‬\n      ‫يقومــوا بذلــك بأنفســهم وأفهمــت املدعيــة بــأن لهــا مطالبــة ابنهــا الثالــث‬\n      ‫‪ ...‬متــى مــا أرادت ذلــك بحصتــه مــن النفقــة وبعرضــه عليهــم قــررت‬\n      ‫املدعيــة القناعــة وقــرر املدعــى عليهمــا عــدم القناعــة وافهمــا بتعليمــات‬\n      ‫التمييــز وأن عليهمــا احلضــور الســبت القــادم ‪1434/7/29‬ه ـ الســتالم‬\n      ‫الصــك لتقــدمي االعتــراض خــال ثالثــن يومــا مــن اســتالمهم للصك وإذا‬\n      ‫لــم يقدمــوا خاللهــا اعتراضهــم فــإن احلكــم ســوف يكتســب القطعيــة‬\n      ‫ففهمــوا ذلــك وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/26‬ه ـ ‪...‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالطائف‬\n      ‫ففــي يــوم الثالثــاء املوافــق ‪1434/8/9‬ه ـ ويف متــام الســاعة احلاديه عشــره‬\n      ‫وعشــر دقائــق صباحــا أفتتحــت اجللســة وقد وردتنا الالئحــه االعتراضيه‬\n      ‫املقدمــه مــن املدعــى عليــه واملقيــده بهــذه احملكمــة برقــم ‪342009249‬‬\n      ‫يف ‪1434/8/21‬ه ـ واملكونــه مــن ســت ورقــات وباالطــاع عليهــا لــم‬\n      ‫اجــد مــا يؤثرعلــى مــا ســبق احلكــم بــه وامــرت باحلــاق ذلــك بضبطــه‬\n      ‫كــي ال يخفــى ورفعهــا مــع كامــل اوراق املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف ففــي يــوم اإلثنــن املوافــق‪ 1434/12/16‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثامنــه والنصــف صباحــا بنــاء علــى رجــوع املعاملــة‬\n      ‫مــن محمكــة االســتئناف مبكــة املكرمــة برقــم ‪ 34746114‬يف‬\n      ‫‪1434/11/24‬ه ـ وبرفقتهــا الصــك الصــادر منــا برقــم ‪34283903‬‬\n\n\n‫‪243‬‬\n\f‫يف ‪1434/7/30‬ه ـ واملظهــر عليــه مبوجــب تظهيــرات الدائــره الثالثــه‬\n‫لالحــوال الشــخصيه واالوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫مبحكمــة االســتئناف مبكــة املكرمــة واملتضمــن بعــد املقدمــة انــه‬\n‫جــرى االطــاع علــى الصــك املشــار اليــه بعاليــه واصدرنــا القــرار رقــم‬\n‫‪ 34357857‬يف ‪1434/11/11‬ه ـ املتضمــن باالكثريــة املوافقــه علــى‬\n‫احلكــم وبــاهلل التوفيــق عضــو ختــم وتوقيــع عضــو ختــم وتوقيــع رئيــس‬\n‫الدائــره ختــم وتوقيــع أ‪.‬ه ـ عليــه فقــد امــرت باحلــاق ذلــك بضبطــه وســجلة‬\n‫كــي ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                         ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/12/16‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 34746114‬وتاريــخ ‪1434/10/29‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة العامــة‬\n‫بالطائــف برقــم ‪ 34283903‬وتاريــخ ‪1434/7/30‬ه ـ ‪ ،‬املتضمــن دعوى‬\n‫املــرأة يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل‬\n                               ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪244‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":237,"source_page_end":244,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bc4f6e2f3645e9a9be8b5807aa416037beb33c1f60648e6bfddd01e8b1c3138c","normalized_text_hash":"3ab33fc35d89c68660a8e2cee268865f47a01f8fdee82fdae39191dde746be50","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p237-34283903"},{"id":"d8879d19-cc82-5ffa-858c-c62fa21d1aae","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة ابن بالغ -النفقة املاضية و املستقبلية -تقدير النفقة عن طريق قسم اخلبراء -احلكم بالنفقة املاضية واملستقبلية .","document_number":"34171996","case_number":"34110811","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض وبتكليف منه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/25","year":"1434","subject":"نفقة -نفقة ابن بالغ -النفقة املاضية و املستقبلية -تقدير النفقة عن طريق قسم اخلبراء -احلكم بالنفقة املاضية واملستقبلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34171996 :‬‬\n                         ‫َر ْق ُم الدعوى‪34110811 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34263405‬تاريخه‪1434/7/9:‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬نفقــة ابــن بالــغ ‪ -‬النفقــة املاضيــة و املســتقبلية ‪ -‬تقدير النفقة‬\n             ‫عن طريق قســم اخلبراء ‪ -‬احلكم بالنفقة املاضية واملســتقبلية ‪.‬‬\n\n\n\n\n                                              ‫قوله تعالى { ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِتهِ}‬\n\n\n\n\n      ‫ادعــى املدعــي أصالــة عــن نفســه وبالوكالــة عــن أخيــه ضــد والدهمــا‬\n      ‫بالوكالــة عنــه أحــد أبنائــه ومضمــون الدعــوى أن املدعيــن قــد خرجــا‬\n      ‫مــن منــزل والدهمــا بســبب طالقــه لوالدتهما ومن تاريــخ ‪1433/11/1‬هـ‬\n      ‫لــم ينفــق عليهمــا وطلــب املدعــي أصالــة ووكالــة إلــزام والدهمــا بالنفقــة‬\n      ‫مــع مراعــاة أجــرة الســكن والســيارة وهمــا طالبــان بالثانويــة أجــاب‬\n      ‫املدعــى عليــه وكالــة باملصادقــة علــى الدعــوى ســوى النفقــة فقــرر أن‬\n      ‫والدهمــا كان ينفــق عليهمــا وســلم املدعــي ‪ 1500‬ريــال وال مانــع لديــه‬\n      ‫مــن النفقــة متــى رجعــا إلــى بيــت والدهمــا أجــاب املدعي أصالــة ووكالة‬\n      ‫بإنــكار النفقــة وقــرر أنــه ال مانــع مــن خصــم مبلــغ ‪ 1500‬مــن املطالبــة مت‬\n      ‫تقديــر نفقــة املدعيــن مبلغـ ًا قــدره ألفــا ريــال لــكل واحــد قــرر املدعــي‬\n      ‫القناعــة وقــرر املدعــى عليــه وكالــة عــدم القناعــة قــرر ناظــر القضيــة‬\n      ‫أن نفقــة األوالد واجبــة عنــد حاجتهــم وخصوص ـ ًا مــع حاجــة األوالد‬\n‫‪245‬‬\n\f‫وغنــى الوالــد وهــم يدرســون يف مرحلــة تتطلــب التفــرغ للدراســة ولقولــه‬\n‫تعالــى { ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ َسـ َـع ِتهِ} ومبــا أن املدعــي قــرر موافقتــه علــى‬\n‫خصــم ‪ 1500‬ريــال وأن يتــم احتســاب النفقــة مــن شــهر ذي القعــدة مــن‬\n‫‪1433/11/1‬ه ـ إلــى ‪1434/3/30‬ه ـ يصبح مجمــوع النفقة مبلغ ًا وقدره‬\n‫عشــرون ألــف ريــال يخصــم منهــا مبلغ ـ ًا قــدره ‪ 1500‬ريــال لذلــك فقــد‬\n‫صــدر احلكــم بإلــزام املدعــى عليــه بتســليم املدعيــن النفقــة املاضيــة‬\n‫مبلغـ ًا قــدره ثمانيــة عشــر ألفـ ًا وخمســمائة ريــال مناصفــة بينهمــا ونفقــة‬\n‫شــهرية قدرهــا ألفــا ريــال لــكل واحــد منهمــا ابتــداء مــن ‪1434/4/1‬ه ـ‬\n‫قــرر املدعــي القناعــة وقــرر املدعــى عليــه وكالــة عــدم القناعــة صــدر‬\n‫قــرار محكمــة االســتئناف باملالحظــة ومضمــون ذلــك أن املدعــي أصالة‬\n‫ووكالــة لــم يذكــر يف دعــواه اســتدانة لتلــك النفقــة تقضــي إيجابهــا‬\n‫علــى الوالــد‪ ،‬ومت عــرض ذلــك علــى املدعــي أصالــة ووكالــة وقــرر‬\n‫أنــه اســتدان تلــك النفقــة صــدر قــرار محكمــة االســتئناف بالريــاض‬\n                                                               ‫باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة‬\n‫الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض وبتكليــف منــه‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالرياض‪/‬املســاعد برقم ‪ 33712469‬وتاريخ ‪ 1433/12/29‬هـ املقيدة‬\n‫باحملكمــة برقــم ‪ 332276534‬وتاريــخ ‪ 1433/12/29‬ه ـ يف يــوم‬\n‫األربعــاء املوافــق‪ 1434/01/28‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬أصالــة عــن نفســه ووكيــا عــن ‪ ...‬مبوجــب‬\n                                                                                                           ‫‪246‬‬\n\f      ‫الوكالــة الصــادرة مــن كتابــة عــدل عرقــة برقــم ‪ 3431860‬بتاريــخ‬\n      ‫‪1434/1/10‬ه ـ املخــول لــه فيهــا املرافعــة واملدافعــة واالقــرار وحضــر‬\n      ‫حلضــوره ‪ ...‬بصفتــه وكيــا عــن والــده مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل عرقــة برقم ‪ 33187628‬وتاريــخ ‪1433/04/13‬هـ واملخول‬\n      ‫لــه فيهــا حــق املرافعــة واملدافعــة واالقــرار والصلــح وبســؤال املدعــي عــن‬\n      ‫دعــواه أجــاب قائــا إنــي وأخــي ‪ ...‬أوالد املدعــى عليــه وقــد خرجنــا مــن‬\n      ‫منــزل والدنــا يف شــهر شــعبان مــن عــام ‪1433‬ه ـ بســبب طالقــه لوالدتنــا‬\n      ‫ومــن تاريــخ ‪1433/11/01‬ه ـ لــم ينفــق علينــا لــذا نطالــب بالنفقــة مــع‬\n      ‫مراعــاة قيمــة أجــرة الســكن والســيارة علمــا أننــي طالــب يف الثانويــة‬\n      ‫وأخــي ‪ ...‬يف الســنة األولــى الثانويــة هــذه دعوانــا وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه وكالــة أجــاب قائــا مــا ذكــره املدعــي يف دعــواه‬\n      ‫كلــه صحيــح مــا عــدا عــدم إنفــاق والــدي حيــث أنــه دفــع للمدعــي‬\n      ‫مبلغــا قــدره ‪ 1500‬ريــال ووالــدي ال مانــع لديــه مــن النفقــة متــى مــا‬\n      ‫مت رجوعهمــا إلــى البيــت كمــا أنــه لــم يخــرج مــن املنــزل إال يف شــهر‬\n      ‫ذي القعــدة هكــذا أجــاب وبعــرض ذلــك علــى املدعيــن قــال املدعــي‬\n      ‫تاريــخ اخلــروج غيــر مؤثــر يف الدعــوى وأمــا مــا ذكــر مــن اســتالمي‬\n      ‫ملبلــغ ‪ 1500‬ريــال غيــر صحيــح ولكــن لعــدم تأخيــر الدعــوى ال مانــع‬\n      ‫مــن خصــم املبلــغ مــن النفقــة وأنــا ذهبــت لوالدتــي لعــدم وجــود محــرم‬\n      ‫معهــا وأنــا أكبــر أوالدهــا وعــدم وجــود مــن يرعانــا يف املنــزل الــذي بــه‬\n      ‫والــدي هكــذا ذكــر بعــد ذلــك اقتضــى النظــر الكتابــة لهيئــة النظــر‬\n      ‫لتقديــر نفقــة للمدعيــن احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف‬\n      ‫احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بالرياض‪/‬املســاعد برقــم ‪ 33712469‬وتاريــخ‬\n\n\n‫‪247‬‬\n\f‫‪ 1433/12/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332276534‬وتاريــخ‬\n‫‪ 1433/12/29‬ه ـ يف يــوم األربعــاء املوافــق‪ 1434/03/25‬ه ـ حضــر‬\n‫املدعــي أصالــة ووكالــة وحضــر حلضورهــم املدعــى عليــه وكالــة وقــد‬\n‫وردنــا قــرار مكتــب الصلــح باحملكمــة رقــم ‪ 237‬يف ‪1434/3/25‬ه ـ‬\n‫واملتضمــن أن تكــون نفقــة الولــد الواحــد مبلغــا قــدره ألفــا ريــال ‪2000‬‬\n‫شــهريا نظــرا حلالــة املدعــى عليــه املاديــة واســتنادا لقولــه تعالــى (لينفــق‬\n‫ذو ســعة مــن ســعته) وبعــرض ذلــك علــى الطرفــن قــرر املدعــي القناعــة‬\n‫بــه وقــرر املدعــى عليــه وكالــة عــدم القناعــة بذلــك لكــون املبلــغ مبالــغ‬\n‫فيــه ويكفــي خمســمائة ريــال لــكل واحــد مــع العلــم أن املدعــن بالغــن‬\n‫وموكلــي ليــس مبلــزم بالنفقــة عليهــم هكــذا ذكــر وبســؤال املدعــى‬\n‫عليــه عــن تاريــخ خــروج املدعــي وأخيــه فقــال ال أذكــر التاريــخ بالضبــط‬\n‫لكنــه يف شــهر ذي القعــده هكــذا ذكــر وبعــرض ذلــك علــى املدعــي‬\n‫قــال انــا خرجــت يف نهايــة شــهر شــوال وال مانــع مــن احتســاب النفقــة مــن‬\n‫بدايــة شــهر ذي القعــده فبنــاء علــى ماتقــدم وملــا جــاء يف قــرار مكتــب‬\n‫الصلــح املســتند يف تقديــره علــى مــاورد مــن أمــاك كثيــرة للمدعــى‬\n‫عليــه وحالتــه املاديــة املمتــازة ولقولــه تعالــى (لينفــق ذو ســعة مــن ســعته)‬\n‫ومبــا أن نفقــة الوالــد ألوالده واجبــة عنــد حاجتهــم وخصوصــا مــع حاجــة‬\n‫األوالد وغنــى الوالــد واليخفــى حاجــة األوالد نظــرا لكونهــم يدرســون‬\n‫يف مرحلــة تتطلــب تفرغهــم للدراســة ومبــا أن املدعــي قــرر موافقتــه‬\n‫علــى خصــم املبلــغ الــذي أدعــى املدعــى عليــه وكالــة تســليمه لــه البالــغ‬\n‫قــدره الــف وخمســمائة ريــال وأن يتــم احتســاب النفقــة مــن بدايــة شــهر‬\n‫ذي القعــده وبإجــراء عمليــة حســابية للنفقــه مــن ‪1433/11/1‬ه ـ إلــى‬\n‫‪1434/3/30‬ه ـ للمدعيــن يصبــح مجمــوع النفقــه قــدره عشــرون ألــف‬\n\n\n                                                                                       ‫‪248‬‬\n\f      ‫ريــال يخصــم منــه الــف وخمســمائة ريــال وجلميــع ماتقــدم فقــد الزمــت‬\n      ‫املدعــى عليــه بــأن يدفــع للمدعيــن مبلــغ النفقــة املاضيــة البالــغ قــدره‬\n      ‫ثمانيــة عشــر الفــا وخمســمائة ريــال مناصفــة بينهمــا ونفقــة شــهرية‬\n      ‫قدرهــا الفــا ريــال ‪ 2000‬لــكل واحــد منهمــا ابتــداء مــن ‪1434/4/1‬ه ـ‬\n      ‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قنــع املدعــي و قــرر‬\n      ‫املدعــى عليــه وكالــة عــدم قناعتــه باحلكــم وطالــب بتدقيــق احلكــم‬\n      ‫واســتعد بتقــدمي الئحــة اعتراضيــة وأفهــم بأنــه لــه مــدة قدرهــا ثالثــون‬\n      ‫يــوم لتقــدمي اعتراضــه اعتبــارا مــن تاريــخ اســتالم صــورة مــن نســخة‬\n      ‫احلكــم وإذا مضــت املــدة احملــددة لالعتــراض ولــم يقــدم الئحتــه فيهــا‬\n      ‫ســقط حقــه يف االســتئناف واكتســب احلكــم القطعيــة وحــدد موعــد‬\n      ‫تســليم صــورة نســخة احلكــم هــذا اليــوم الســاعة ‪ 1.30‬ومت إقفــال‬\n      ‫اجللســة الســاعة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 33712469‬وتاريــخ ‪ 1433/12/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332276534‬وتاريــخ ‪ 1433/12/29‬ه ـ يف يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/06/14‬ه ـ حضــر ‪ ...‬حيــث عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبوجــب خطــاب رئيــس محكمــة االســتئناف‬\n      ‫رقــم ‪ 341156291‬يف ‪1434/6/6‬ه ـ وبرفقهــا قــرار املالحظــة‬\n      ‫الصــادر مــن الدائــرة االحــوال الشــخصية الثانيــة برقــم ‪ 34223302‬يف‬\n      ‫‪1434/5/26‬ه ـ ونــص احلاجــة منــه( ماحكــم بــه فضيلتــه مــن النفقــة‬\n      ‫لــاوالد املذكوريــن قــد انفقــا علــى انفســهما ولــم يذكــرا يف دعواهمــا‬\n\n\n‫‪249‬‬\n\f‫اســتدانة لتلــك النفقــة تقتضــي إيجــاب النفقــة علــى والدهمــا فمــا وجــه‬\n‫مــا حكــم بــه فضيلتــه واحلــال تلــك وبعــرض ذلــك علــى املدعــي احلاضــر‬\n‫أجــاب قائــا املــدة مــن تاريــخ عــدم االنفــاق بتاريــخ ‪1433/11/1‬ه ـ حتــى‬\n‫إقامــة الدعــوى بتاريــخ ‪1434/12/29‬ه ـ قرابــة الشــهرين وكنــا نحــاول‬\n‫حــل األمــر وديــا مــع والــدي ولكــن ظهــر لنــا تدخــل اخينــا لالفســاد بيننــا‬\n‫وكنــا يف حالــة ال يعلــم بهــا اال اهلل حيــث اســتأجر جــدي لنــا غرفتــن يف‬\n‫ســطح مــع أن والــدي غنــي وكنــت أســتلف املبالــغ مــن جــدي وســأعيدها‬\n‫لــه عنــد اســتالم مبالــغ النفقــة واآلن حالتنــا تــزداد ســؤا يومــا بعــد يــوم‬\n‫لطــول املــدة هكــذا أجــاب وبذلــك مت إكمــال الــازم حيــال مالحظــة‬\n‫أصحــاب الفضيلــة وأمــرت بإحلــاق ذلــك علــى صــك احلكــم وســجله‬\n‫وبــاهلل التوفيــق وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 33712469‬وتاريــخ ‪ 1433/12/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332276534‬وتاريــخ ‪ 1433/12/29‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/07/23‬ه ـ حيــث عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف وبرفقهــا القــرار املــدون علــى ظهــر الصــك واملتضمــن مــا‬\n‫نصــه ( تظهيــرات الدائــرة الثانيــة لألحــوال الشــخصية واإلنهــاءات‬\n‫مبحكمــة االســتئناف بالريــاض احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا‬\n‫علــى هــذا الصــك رقــم ‪ 34171996‬وتاريــخ ‪1434/3/25‬ه ـ الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة العامــة بالريــاض الشــيخ ‪ ...‬وأصدرنــا‬\n‫القــرار رقــم ‪ 34263405‬وتاريــخ ‪1434/7/9‬ه ـ املتضمــن املصادقــة‬\n\n\n                                                                                       ‫‪250‬‬\n\f      ‫علــى احلكــم واهلل املوفــق قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي‬\n      ‫اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه ) وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/07/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 341565480‬وتاريــخ ‪1434/7/1‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪... /‬‬\n      ‫املســجل برقــم ‪ 34171996‬وتاريــخ ‪1434/3/25‬ه ـ اخلــاص بدعــوى‪... /‬‬\n      ‫اصالــة ووكالــة عــن اخيــه ‪ ...‬ضــد ‪ /‬والدهــم ‪ .‬يف قضيــة نفقــة وقــد‬\n      ‫تضمــن الصــك حكــم فضيلتــه مباهــو مــدون ومفصــل فيــه‪ .‬وحيث ســبق‬\n      ‫دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى‬\n      ‫قرارنــا رقــم ‪ 34223302‬وتاريــخ ‪1434/5/26‬ه ـ تقــرر الدائرة املصادقة‬\n      ‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى‬\n                                                                 ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪251‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":245,"source_page_end":251,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1af6d263a8f344f3e951c912f2303904933b68ef0949a997722357ef8d847d81","normalized_text_hash":"0e3261dec1c48e8c804bfedbb93477eaae2de1fc44cff8ad5e6d4f0b23ed5654","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p245-34171996"},{"id":"208539b6-12d0-5c2d-9cc0-287a57573c17","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة حامل -نفقة طفل عن املدة املاضية واملستقبلية - نفقة احلامل التسقط بالنشوز -تقدير النفقة عن طريق قسم اخلبراء -اإلقرار حجة موجبة بنفسه -إلزام املدعى عليه بدفع نفقة الطفل املاضية و املستقبلية ونفقة احلمل .","document_number":"34177730","case_number":"3434673","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"نفقة -نفقة حامل -نفقة طفل عن املدة املاضية واملستقبلية - نفقة احلامل التسقط بالنشوز -تقدير النفقة عن طريق قسم اخلبراء -اإلقرار حجة موجبة بنفسه -إلزام املدعى عليه بدفع نفقة الطفل املاضية و املستقبلية ونفقة احلمل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/2 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34177730 :‬‬\n                     ‫َر ْق ُم الدعوى‪3434673 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 34285592‬تاريخه‪1434/8/2 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة حامــل‪ -‬نفقــة طفــل عــن املــدة املاضيــة واملســتقبلية ‪-‬‬\n‫نفقــة احلامــل التســقط بالنشــوز‪ -‬تقديــر النفقــة عــن طريــق قســم‬\n‫اخلبــراء ‪ -‬اإلقــرار حجــة موجبــة بنفســه ‪ -‬إلــزام املدعــى عليــه بدفــع‬\n                 ‫نفقــة الطفــل املاضيــة و املســتقبلية ونفقــة احلمــل ‪.‬‬\n\n\n\n\n‫‪ -1‬قال يف كشــاف القناع (‪( )125/13‬فتجب النفقة على زوج لزوجته‬\n                                                 ‫ال )‬\n                                                   ‫ناشــز ًا حام ً‬\n                            ‫‪ -2‬قاعدة‪ :‬اإلقرار حجة موجبه بنفسه‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــه أصالــة كان زوجــا لهــا وقــد طلقهــا‬\n‫وهــي حامــل ثــم وضعــت بعــد خمســة أشــهر مــن الطــاق ولــم يراجعهــا‬\n‫ولــم ينفــق عليهــا وال علــى طفلهــا الــذي هــو يف حضانتهــا حتــى اآلن‪-‬‬\n‫طلبــت املدعيــة نفقــة احلمــل خمســة أشــهر والنفقــة املاضيــة للطفــل ملــدة‬\n‫ســنتني وأربعــة أشــهر وتقريــر النفقــة املســتقبلية للطفــل‪ -‬أقــر املدعــى‬\n‫عليــة وكالــة بصحــة مــا جــاء يف الدعــوى ودفــع بــأن ســبب عــدم النفقــة‬\n‫علــى املدعيــة مــدة احلمــل هــو نشــوزها وال مانــع لــدى موكلــه مــن دفــع‬\n\n\n                                                                                   ‫‪252‬‬\n\f      ‫نفقــة ابنــه املاضيــة واملســتقبلية‪ -‬ورد اجلــواب مــن قســم اخلبــراء بتحديــد‬\n      ‫نفقــة مــدة احلمــل ونفقــة الطفــل عــن املــدة املاضيــة واملســتقبلة‪ -‬حيــث إن‬\n      ‫اإلقــرار حجــة موجبــة وملــا ذكــره صاحــب كشــاف القنــاع مــن وجــوب‬\n      ‫ا لــذا صــدر احلكم‬     ‫النفقــة علــى الــزوج لزوجتــه الناشــز إذا كانــت حامـ ً‬\n      ‫علــى املدعــى عليــه بدفــع نفقــة احلمــل للمدعيــة وكذلــك دفــع نفقــة ابنــه‬\n      ‫عــن املــدة املاضيــة وإلزامــه بدفــع النفقــة املســتقبلة وفــق تقديــر قســم‬\n      ‫اخلبــراء‪ -‬قنعــت املدعيــة ولــم يقنــع املدعــى عليــه‪ -‬صــدق احلكــم مــن‬\n                                                             ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده والصالة والســام على من ال نبي بعده وبعد‪ :‬ففي هذا‬\n      ‫اليــوم االثنــن املوافــق ‪1434/3/2‬ه ـ ويف متــام الســاعة العاشــرة صباحـ ًا‬\n      ‫لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بالطائــف بنــاء علــى املعاملــة‬\n      ‫احملالــة مــن فضيلــة الرئيــس برقــم ‪ 3434673‬وتاريــخ ‪1434/1/19‬ه ـ‬\n      ‫واملقيــدة يف هــذه احملكمــة برقــم ‪ 34167668‬وتاريــخ ‪1434/1/19‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــرت ‪...‬ســعودية اجلنســية بالســجل املدنــي رقم‬\n      ‫‪...‬مدعيــة علــى احلاضــر يف مجلــس احلكــم ‪...‬ســعودي اجلنســية بالســجل‬\n      ‫ا عــن ‪...‬ســعودي اجلنســية بالســجل املدنــي‬   ‫املدنــي رقــم ‪...‬بصفتــه وكي ـ ً‬\n      ‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف‬\n      ‫برقــم ‪ 33277549‬يف ‪1433/9/19‬ه ـ قائلــة يف دعواهــا ضــده‪ :‬كان‬\n      ‫املدعــى عليــه أصالــة زوج ـ ًا لــي وقــد طلقنــي وأنــا حامــل يف شــهر رجــب‬\n      ‫لعــام ‪1431‬ه ـ ثــم وضعــت احلمــل بعــد خمســة أشــهر مــن الطــاق ولــم‬\n      ‫يراجعنــي ولــم ينفــق علــي وال علــى طفله ‪...‬الذي هو يف حضانتي إلى اآلن‬\n‫‪253‬‬\n\f‫لــذا فإنــي أطلــب نفقــة احلمــل خمســة أشــهر والنفقــة املاضيــة ملــدة ســنتني‬\n‫وأربعــة أشــهر وتقريــر النفقــة املســتقبلية البننــا ‪...‬هــذه دعــواي وعليهــا‬\n‫أوقــع وبعرضهــا علــى املدعــى عليــه وكالــة أجــاب قائ ـاً‪ :‬مــا ذكرتــه‬\n‫مــن زواج موكلــي بهــا وطالقــه لهــا وهــي حامــل وإجنابهــا للطفــل ‪...‬علــى‬\n‫فــراش الزوجيــة فهــذا صحيــح ومــا ذكرتــه مــن عــدم انفــاق موكلــي‬\n‫عليهــا فتــرة احلمــل بعــد طالقــه لهــا فهــذا صحيــح والســبب هــو أن والدهــا‬\n‫منــع موكلــي مــن أخذهــا ملنزلــه وهــي ناشــز فتــرة احلمــل وال أذكــر املــدة‬\n‫بالتحديــد وأمــا مــا طلبتــه مــن نفقــة البنهــا ‪...‬للفتــرة املاضيــة والفتــرة‬\n‫املســتقبلية فــا مانــع لــدى موكلــي مــن دفعهــا هكــذا أجــاب وبســؤال‬\n‫الطرفــن عــن صــك الطــاق وتاريــخ ميــاد الطفــل أجابــت املدعيــة بأنهــا‬\n‫تطلــب مهلــة إلحضارهــا هكــذا طلبــت وقــد جــرت منــا إحالــة الطرفــن‬\n‫لقســم الصلــح والتحكيــم يف هــذه احملكمــة للمحاولــة اإلصــاح‬\n‫وتقديــر النفقــة فوردنــا قرارهــم رقــم ‪/57‬ص يف ‪1434/2/6‬ه ـ متضمنـ ًا‬\n‫مــا نصــه‪ (( :‬حضــرت املدعيــة أصالــة ‪ ...‬وحضــر حلضورهــا املدعــى عليــه‬\n‫وكالــة ‪...‬ومبحاولــة الصلــح وتقريــب وجهــات النظــر بينهمــا تعذر الصلح‬\n‫بــن الطرفــن وحيــث أفــاد وكيــل املدعــى عليــه أن موكلــه يتقاضــى‬\n‫راتــب وقــدره تســعة اآلف ريــال عليــه تــرى اللجنــة والــرأي لفضيلتكــم‬\n‫أن تكــون نفقــة الطفــل املاضيــة واملســتقبلية ثمامنائــة ريــال ونفقــة احلمــل‬\n‫للمدعيــة ألــف ريــال وبــاهلل التوفيــق وصلــى اهلل وســلم عــى نبينــا محمــد‬\n‫وعلــى الــه وصحبــه وســلم أعضــاء جلنــة الصلــح ‪...‬و‪ ......‬و‪...‬و ‪...‬رئيــس‬\n‫قســم الصلــح ‪...‬توقيعهــم )) أ‪.‬ه ـ وبتالوتــه علــى الطرفــن قــررت املدعيــة‬\n‫قبولهــا بــه وأمــا وكيــل املدعــى عليــه فقــال‪ :‬أنــا معتــرض علــى النفقــة‬\n‫فتــرة احلمــل وأمــا نفقــة الطفــل فــأرى أنهــا كثيــرة ألن موكلــي يــرمم يف‬\n\n\n                                                                                      ‫‪254‬‬\n\f      ‫منزلــه ومقبــل علــى زواج هكــذا أجــاب والنتهــاء وقــت اجللســة قــررت‬\n      ‫رفعهــا يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا وحــددت للطرفــن‬\n      ‫موعــد ًا يف يــوم األحــد املوافــق ‪1434/3/29‬ه ـ يف متــام الســاعة التاســعة‬\n      ‫صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                       ‫‪ 1434/3/2‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم األحــد املوافــق ‪1434/3/29‬ه ـ ويف متــام الســاعة التاســعة‬\n      ‫صباح ـ ًا لــدي أنا‪......‬القاضــي يف احملكمــة العامــة بالطائــف القائــم‬\n      ‫بعمــل املكتــب القضائــي الســابع افتتحــت اجللســة وفيهــا حضــرت‬\n      ‫‪...‬معرفـ ًا بهــا مــن قبــل والدتهــا ‪...‬ســعودية اجلنســية بالســجل املدنــي رقــم‬\n      ‫‪...‬واملعــرف بوالدتهــا مــن قبــل املشــرفة علــى تفتيــش النســاء ‪...‬حيــث إنــه‬\n      ‫متــت مطابقــة بطاقــة االحــوال ذات الرقــم فوجــدت مطابقــة وحضــر‬\n      ‫ا عــن ‪...‬وحيــث تبــن أن قــرار مكتــب الصلــح غيــر‬      ‫حلضورهــا ‪...‬وكي ـ ً‬\n      ‫واضــح لــذا فقــد قــررت إعــادة املعاملــة إلــى مكتــب الصلــح لإلفــادة عــن‬\n      ‫قرارهــم وتفســير مــا ورد فيــه عليــه قــررت رفــع اجللســة يف متــام الســاعة‬\n      ‫التاســعة والنصــف صباح ـ ًا وحــددت للطرفــن موعــد ًا يف يــوم الثالثــاء‬\n      ‫املوافــق ‪ 1434/4/2‬يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪ 1434/3/29‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪ 1434/4/2‬ويف متــام الســاعة العاشــرة‬\n      ‫والنصــف صباح ـ ًا لــدي أنا‪......‬القاضــي يف احملكمــة العامــة بالطائــف‬\n      ‫القائــم بعمــل املكتــب القضائــي الســابع افتتحــت اجللســة وفيهــا حضرت‬\n      ‫ا عــن ‪ ......‬وقــد عــادت إلينــا املعاملــة مــن‬\n                                                       ‫‪...‬وحضــر حلضورهــا ‪...‬وكيـ ً‬\n\n\n‫‪255‬‬\n\f‫رئيــس قســم الصلــح وذلــك بعــد أن متــت مخاطبتهــم لإلفــادة عــن تفســير‬\n‫مــا ورد يف قرراهــم املشــار إليــه أعــاه فوردنــا شــرح رئيــس قســم الصلــح‬\n‫علــى خطابنــا رقــم ‪ 34787904‬يف ‪1434/4/1‬ه ـ واملتضمــن ((حيــث أن‬\n‫اللجنــة تــرى أن تكــون نفقــة احلمــل ألــف ريــال لــكل شــهر )) فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي عليــه أقــر بأنــه ال مانــع‬\n‫لــدى موكلــه مــن دفــع نفقــة ابنــه ‪ ...‬للفتــرة املاضيــة والفتــرة املســتقبلية‬\n‫واإلقــرار حجــة موجبــة بنفســه فيقضــي بــه ومبــا أن أهل اخلبــرة قد قدروا‬\n‫النفقــة املاضيــة واملســتقبلية بثمامنائــة ريــال حســب مــا ورد يف قرارهــم‬\n‫رقــم ‪/75‬ص يف ‪1434/2/6‬ه ـ وحيــث أنــه ال يســوغ االســتغناء علــى مــا‬\n‫قــرره أهــل اخلبــرة إال اذا ظهــر عيــب فيمــا قــرروه ولــم يظهــر لــي شــيء‬\n‫يف ذلــك وملــا ورد يف كشــاف القنــاع مــا نصــه (( فتجــب النفقــة علــى‬\n‫زوج لزوجتــه ناشــز ًا حامــل )) ‪ . 125/13‬لذلــك كلــه فقــد حكمــت‬\n‫علــى املدعــى عليــه أصالــة ‪...‬بدفــع مبلــغ وقــدره ســبعة وعشــرون ألف ـ ًا‬\n‫وأربعمائــة ريــال نفقــة ل‪ ...‬ابــن املدعــى عليــه وأيضـ ًا نفقــة للحمــل كمــا‬\n‫حكمــت علــى املدعــى عليــه باالســتمرار يف دفــع النفقــة املســتقبلية مبلــغ‬\n‫وقــدره ثمامنائــة ريــال شــهري ًا ويبــدأ يف دفعهــا مــن تاريــخ ‪1434/5/25‬ه ـ‬\n‫وبعــرض احلكــم علــى طــريف الدعــوى قــررت املدعيــة قناعتهــا باحلكــم‬\n‫وأمــا املدعــى عليــه فقــرر اعتراضــه علــى احلكــم وطلــب االســتئناف‬\n‫بالئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف بــأن لــه ثالثــون يوم ـ ًا‬\n‫مــن تاريــخ اســتالمه نســخة مــن صــك احلكــم وان لــم يتقــدم بالئحــة‬\n‫اعتراضيــه خــال هــذه الفتــرة فيســقط حقــه يف االعتــراض ويكتســب‬\n‫الصفــة القطعيــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم حــرر يف ‪1434/4/2‬ه ـ‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائف‬\n      ‫فقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب فضيلــة رئيســها‬\n      ‫املكلــف برقــم ‪ 34167668‬يف ‪1434/6/5‬ه ـ وبرفقهــا القــرار الصــادر‬\n      ‫مــن الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار‬\n      ‫وبيــوت املــال برقــم ‪ 34228128‬يف ‪1434/6/3‬ه ـ املتضمــن مــا نصــه بعد‬\n      ‫املقدمــة‪ (( :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقرر‬\n      ‫باألكثريــة إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن املعتــرض ذكــر‬\n      ‫وجــود دعــوى ســابقة بينهمــا يف زيــارة لالبــن ‪...‬وصــدر بذلــك الصــك رقــم‬\n      ‫‪ 3417287‬يف ‪1434/1/20‬ه ـ ولــم جنــد صــورة مــن هــذا الصــك والبــد‬\n      ‫مــن ارفــاق صــورة مكتملــة مــن الصك املذكــور واهلل املوفق وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــة وصحبــه وســلم قاضــي اســتئناف ‪...‬ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ‪ ...‬موافــق علــى احلكــم ختمــه وتوقيعــه‬\n      ‫رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه )) أ‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة‬\n      ‫بأنــه جــرى إرفــاق صــورة مكتملــة مــن صــك الزيــارة رقــم ‪3417287‬‬\n      ‫يف ‪1434/1/20‬ه ـ وأمــرت بإعــادة أوراق املعاملــة حملكمــة االســتئناف‬\n      ‫إلكمــال الــازم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                           ‫حــرر يف ‪1434/7/12‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n      ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 34167668‬وتاريــخ ‪1434/7/19‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة‬\n\n\n‫‪257‬‬\n\f‫بالطائــف برقــم ‪ 34177730‬وتاريــخ ‪1434/4/2‬ه ـ ‪ ،‬املتضمــن دعــوى‬\n‫املــرأة ‪...‬ضــد ‪ ...‬يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل‬\n     ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪258‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":252,"source_page_end":258,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e6cc3aefc50cc372b8b4903d8f83f33b26a9619e242307e0f36d440597928979","normalized_text_hash":"ab73df76e4d86f248bb3115c1aebd7c8f9c6cb953c4aff4a6394d40e682bf3a5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p252-34177730"}]$archive_payload$::jsonb AS data)
